// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title GrievanceTypes
 * @notice Foundational type definitions for the Blockchain-Based Public Grievance Tracking System.
 *
 * This file defines all shared enums, structs, and custom errors used across the grievance
 * management contract suite. It contains NO business logic — only reusable data types and
 * error definitions.
 *
 * Architecture notes:
 * - File-level definitions allow selective imports: `import { Status, Grievance } from "./GrievanceTypes.sol";`
 * - Enums enforce named state transitions; consuming contracts must never rely on raw integer values.
 * - Structs are designed for append-only historical records where immutability matters
 *   (e.g., InvestigationNote, Assignment) and mutable state where necessary (e.g., Grievance.status).
 * - Large text content (descriptions, resolution details, investigation notes) is stored off-chain
 *   and referenced on-chain via an IPFS CID (for retrieval) and a bytes32 content hash (for
 *   integrity verification). This dual-reference pattern keeps gas costs practical while enabling
 *   a fully backend-free DApp.
 * - Evidence files are NEVER stored on-chain; only IPFS CIDs and content hashes are recorded.
 * - Grievance categories are NOT an enum. They use a dynamic `uint256 categoryId` referencing a
 *   category registry managed by a future contract. This allows the Super Admin to create,
 *   activate, and deactivate categories at runtime without redeploying contracts.
 */

// ============================================================================
//  ENUMS
// ============================================================================

/**
 * @notice Grievance lifecycle status.
 * @dev Transitions are enforced by GrievanceSystem.sol — not by this type definition.
 *
 * Lifecycle flow:
 *   SUBMITTED → REGISTERED → ASSIGNED → UNDER_REVIEW → UNDER_INVESTIGATION
 *   → RESOLUTION_PROPOSED → CITIZEN_REVIEW → ACCEPTED → CLOSED
 *
 * Rejection path:
 *   CITIZEN_REVIEW → REJECTED → REOPENED → ASSIGNED → ...
 *
 * Escalation path:
 *   UNDER_INVESTIGATION → ESCALATED → UNDER_INVESTIGATION
 */
enum Status {
    SUBMITTED,              // 0 — Citizen has submitted the grievance
    REGISTERED,             // 1 — Department has validated and registered intake
    ASSIGNED,               // 2 — Department Admin has assigned to an Officer
    UNDER_REVIEW,           // 3 — Assigned Officer is reviewing the grievance
    UNDER_INVESTIGATION,    // 4 — Active investigation underway
    RESOLUTION_PROPOSED,    // 5 — Officer has proposed a resolution
    CITIZEN_REVIEW,         // 6 — Awaiting citizen feedback on proposed resolution
    ACCEPTED,               // 7 — Citizen has accepted the resolution
    CLOSED,                 // 8 — Grievance fully closed after acceptance
    REJECTED,               // 9 — Citizen has rejected the proposed resolution
    REOPENED,               // 10 — Grievance reopened after citizen rejection
    ESCALATED               // 11 — Escalated due to SLA breach or admin action
}

/**
 * @notice Grievance priority tier, used for SLA deadline computation.
 * @dev Intended SLA durations (configured in EscalationManager, not here):
 *      LOW = 14 days, MEDIUM = 7 days, HIGH = 3 days, CRITICAL = 24 hours.
 *
 * Priority is a fixed enum (unlike Category) because the SLA system depends on a
 * bounded, well-defined set of tiers. Adding a new priority tier would require
 * corresponding SLA configuration — a contract upgrade scenario regardless.
 */
enum Priority {
    LOW,        // 0
    MEDIUM,     // 1
    HIGH,       // 2
    CRITICAL    // 3
}

/**
 * @notice Application-level user role designation.
 * @dev This enum represents role *categories* for data modelling purposes only.
 *      Actual on-chain authorization and permission enforcement is handled by
 *      RoleManager.sol (which will use OpenZeppelin AccessControl).
 *      This enum does NOT grant or check permissions.
 */
enum Role {
    CITIZEN,            // 0 — Default role for any connected wallet
    OFFICER,            // 1 — Government official assigned to a department
    DEPARTMENT_ADMIN,   // 2 — Oversees an entire department
    SUPER_ADMIN         // 3 — System-wide administrator
}

/**
 * @notice Type classification for submitted evidence files.
 * @dev Evidence files are stored on IPFS; only the CID and metadata are on-chain.
 */
enum EvidenceType {
    DOCUMENT,   // 0 — PDFs, text files, official documents
    IMAGE,      // 1 — Photos, screenshots
    VIDEO,      // 2 — Video recordings
    AUDIO,      // 3 — Audio recordings
    OTHER       // 4 — Any other file type
}

/**
 * @notice Status of a proposed resolution from the citizen's perspective.
 */
enum ResolutionStatus {
    PENDING,    // 0 — Resolution proposed, awaiting citizen review
    ACCEPTED,   // 1 — Citizen accepted the resolution
    REJECTED    // 2 — Citizen rejected the resolution
}

/**
 * @notice Enumeration of all auditable actions in the system.
 * @dev Used by AuditTrail.sol to categorize immutable audit log entries.
 *      Every significant state mutation in the system should map to one of these actions.
 */
enum AuditAction {
    USER_REGISTERED,            // 0
    ROLE_GRANTED,               // 1
    ROLE_REVOKED,               // 2
    DEPARTMENT_CREATED,         // 3
    DEPARTMENT_UPDATED,         // 4
    DEPARTMENT_DEACTIVATED,     // 5
    OFFICER_ADDED,              // 6
    OFFICER_REMOVED,            // 7
    GRIEVANCE_CREATED,          // 8
    GRIEVANCE_REGISTERED,       // 9
    GRIEVANCE_ASSIGNED,         // 10
    GRIEVANCE_REASSIGNED,       // 11
    STATUS_CHANGED,             // 12
    INVESTIGATION_STARTED,      // 13
    INVESTIGATION_NOTE_ADDED,   // 14
    EVIDENCE_ADDED,             // 15
    EVIDENCE_REVOKED,           // 16
    RESOLUTION_SUBMITTED,       // 17
    RESOLUTION_ACCEPTED,        // 18
    RESOLUTION_REJECTED,        // 19
    GRIEVANCE_REOPENED,         // 20
    GRIEVANCE_ESCALATED,        // 21
    GRIEVANCE_CLOSED,           // 22
    SLA_UPDATED,                // 23
    CATEGORY_CREATED,           // 24
    CATEGORY_UPDATED,           // 25
    DEPARTMENT_ACTIVATED,       // 26
    CATEGORY_DEACTIVATED,       // 27
    CATEGORY_ACTIVATED,         // 28
    DEPARTMENT_ADMIN_ASSIGNED,  // 29
    DEPARTMENT_ADMIN_REMOVED,   // 30
    GRIEVANCE_REJECTED          // 31
}

// ============================================================================
//  STRUCTS
// ============================================================================

/**
 * @notice Core grievance record.
 * @dev Storage layout note: address (20 bytes) + Status (1 byte) + Priority (1 byte) +
 *      uint8 reopenCount (1 byte) pack into a single 32-byte slot (23 bytes used).
 *      The three uint64 timestamps (createdAt + updatedAt + slaDeadline = 24 bytes) pack
 *      into a single slot.
 *
 * Design decisions:
 * - `title` is a short string stored on-chain for human-readable identification in lists
 *   and event logs. Citizens and admins need a quick identifier without querying IPFS.
 * - `descriptionCid` is the IPFS Content Identifier where the full description text is stored,
 *   enabling the frontend to retrieve and display the content without a backend.
 * - `descriptionHash` is a bytes32 keccak256 hash of the full description text, enabling
 *   on-chain integrity verification of the off-chain content.
 * - `categoryId` is a uint256 referencing a dynamic category registry (NOT a fixed enum).
 *   This allows the Super Admin to create, activate, and deactivate categories at runtime.
 *   A Solidity enum would freeze the category set at deployment time.
 * - `assignedOfficer` is address(0) when unassigned.
 * - `currentResolutionId` is 0 when no resolution has been proposed.
 * - `reopenCount` tracks how many times a grievance has been reopened (max 255).
 */
struct Grievance {
    uint256 id;                     // Unique grievance identifier (generated by GrievanceSystem)
    address citizen;                // Wallet address of the citizen who filed the grievance
    Status status;                  // Current lifecycle status
    Priority priority;              // Priority tier (determines SLA deadline)
    uint8 reopenCount;              // Number of times this grievance has been reopened
    address assignedOfficer;        // Wallet address of the assigned officer (address(0) if unassigned)
    uint256 departmentId;           // ID of the responsible department
    uint256 categoryId;             // ID referencing the dynamic category registry
    string title;                   // Short on-chain title (kept brief to control gas)
    string descriptionCid;          // IPFS CID of the full description text (for retrieval)
    bytes32 descriptionHash;        // keccak256 hash of the full description (for integrity)
    uint64 createdAt;               // Timestamp when the grievance was submitted
    uint64 updatedAt;               // Timestamp of the most recent status change
    uint64 slaDeadline;             // SLA deadline timestamp (computed by EscalationManager)
    uint256 currentResolutionId;    // ID of the active resolution proposal (0 if none)
}

/**
 * @notice Dynamic category record for grievance classification.
 * @dev Categories are managed by a future contract (not by a fixed enum).
 *      The Super Admin can create, activate, and deactivate categories at runtime.
 *      This struct defines the data shape; management logic belongs in DepartmentManager
 *      or a dedicated CategoryManager contract.
 */
struct GrievanceCategory {
    uint256 id;             // Unique category identifier
    uint256 departmentId;   // Department this category belongs to (0 if global/system-wide)
    string name;            // Human-readable category name (e.g., "Infrastructure")
    string description;     // Brief description of what this category covers
    bool isActive;          // Whether this category is currently available for new grievances
    uint64 createdAt;       // Timestamp when the category was created
}

/**
 * @notice Department registry record.
 */
struct Department {
    uint256 id;             // Unique department identifier
    string name;            // Department name (e.g., "Public Works", "Health Services")
    address admin;          // Wallet address of the Department Admin
    bool isActive;          // Whether the department is currently operational
    uint64 createdAt;       // Timestamp when the department was registered
    uint64 updatedAt;       // Timestamp of the last modification
}

/**
 * @notice Evidence metadata record.
 * @dev The evidence record's core data (id, grievanceId, submitter, CID, contentHash,
 *      evidenceType, submittedAt) is immutable once created — never overwritten or deleted.
 *
 *      `isActive` is the sole mutable field. It represents administrative validity:
 *      - true: evidence is considered valid and relevant.
 *      - false: evidence has been administratively revoked (e.g., found to be fraudulent,
 *        irrelevant, or submitted in error).
 *      Revocation does NOT delete the record. The historical evidence entry, its CID, and
 *      its content hash remain permanently on-chain. Revocations are additionally recorded
 *      by the AuditTrail (EVIDENCE_REVOKED action) for full traceability.
 *
 * Design: `ipfsCid` is stored as a string because IPFS CIDv1 strings (e.g., base32/base58)
 * can exceed 32 bytes. `contentHash` is the keccak256 of the raw file bytes for
 * on-chain integrity verification independent of the IPFS layer.
 */
struct Evidence {
    uint256 id;             // Unique evidence identifier
    uint256 grievanceId;    // ID of the associated grievance
    address submitter;      // Wallet address of the uploader (citizen or officer)
    EvidenceType evidenceType;  // Classification of the evidence file
    bool isActive;          // Administrative validity flag (see @dev note above)
    string ipfsCid;         // IPFS Content Identifier (CIDv0 or CIDv1 string)
    bytes32 contentHash;    // keccak256 hash of the raw evidence file
    uint64 submittedAt;     // Timestamp when the evidence was submitted
}

/**
 * @notice Investigation note — an immutable, append-only record.
 * @dev Investigation notes are NEVER overwritten. Each note during an investigation creates
 *      a new InvestigationNote entry, preserving a complete chronological history.
 *
 *      `contentHash` is the keccak256 of the full note text (stored off-chain via IPFS).
 *      `contentCid` is the IPFS CID for retrieval.
 *
 *      This struct is intentionally decoupled from the AuditAction enum. Investigation notes
 *      are investigation-specific data; the AuditTrail contract independently records the
 *      system-wide INVESTIGATION_NOTE_ADDED action. Coupling them would create an unnecessary
 *      dependency between the investigation layer and the audit layer.
 */
struct InvestigationNote {
    uint256 id;             // Unique note identifier
    uint256 grievanceId;    // ID of the associated grievance
    address investigator;   // Wallet address of the officer who authored the note
    string contentCid;      // IPFS CID of the full note text (for retrieval)
    bytes32 contentHash;    // keccak256 hash of the note content (for integrity)
    uint64 timestamp;       // Timestamp when the note was recorded
}

/**
 * @notice Assignment record — tracks grievance assignment and reassignment history.
 * @dev Each assignment or reassignment creates a new record (append-only).
 *      This ensures a full audit trail of who assigned what to whom and when.
 */
struct Assignment {
    uint256 grievanceId;    // ID of the associated grievance
    uint256 departmentId;   // ID of the department the grievance is assigned to
    address assignedOfficer;    // Wallet address of the officer receiving the assignment
    address assignedBy;     // Wallet address of the admin who made the assignment
    uint64 assignedAt;      // Timestamp of the assignment
}

/**
 * @notice Resolution proposal record.
 * @dev A grievance may have multiple resolution proposals over its lifecycle
 *      (e.g., after rejection and reopening). Each proposal is a separate record.
 *
 * `resolutionCid` is the IPFS CID for retrieving the full resolution description.
 * `resolutionHash` is the keccak256 for on-chain integrity verification.
 * `rejectionReasonHash` is bytes32(0) unless the resolution was rejected.
 */
struct Resolution {
    uint256 id;                     // Unique resolution identifier
    uint256 grievanceId;            // ID of the associated grievance
    address proposedBy;             // Wallet address of the officer who proposed the resolution
    ResolutionStatus status;        // Current review status (Pending / Accepted / Rejected)
    string resolutionCid;           // IPFS CID of the resolution description (for retrieval)
    bytes32 resolutionHash;         // keccak256 hash of the resolution description (for integrity)
    bytes32 rejectionReasonHash;    // keccak256 hash of citizen's rejection reason (bytes32(0) if N/A)
    uint64 proposedAt;              // Timestamp when the resolution was proposed
    uint64 reviewedAt;              // Timestamp when the citizen reviewed (0 if still pending)
}

/**
 * @notice Immutable audit log entry.
 * @dev Every significant system action is recorded as an AuditEntry.
 *      Entries are append-only and cannot be modified or deleted.
 */
struct AuditEntry {
    uint256 id;             // Unique audit entry identifier
    AuditAction action;     // The type of action that occurred
    address actor;          // Wallet address of the user who performed the action
    uint256 targetId;       // Context-dependent: grievance ID, department ID, or 0
    bytes32 detailsHash;    // keccak256 hash of any additional detail text (off-chain)
    uint64 timestamp;       // Timestamp when the action was recorded
}

// ============================================================================
//  CUSTOM ERRORS
// ============================================================================

// --- Access & Authorization ---
/// @notice Caller does not have the required role for this operation.
error Unauthorized(address caller, string requiredRole);

/// @notice Operation attempted on a zero address where a valid address is required.
error ZeroAddressNotAllowed();

// --- Grievance Errors ---
/// @notice Referenced grievance does not exist.
error GrievanceNotFound(uint256 grievanceId);

/// @notice The requested status transition is not permitted from the current status.
error InvalidStatusTransition(uint256 grievanceId, Status currentStatus, Status targetStatus);

/// @notice Caller is not the citizen who filed this grievance.
error NotGrievanceOwner(uint256 grievanceId, address caller);

/// @notice The grievance title is empty or exceeds the allowed length.
error InvalidTitle();

// --- Category Errors ---
/// @notice Referenced category does not exist in the dynamic category registry.
error CategoryNotFound(uint256 categoryId);

/// @notice The category is deactivated and cannot be used for new grievances.
error CategoryNotActive(uint256 categoryId);

/// @notice A category with this name already exists in this department.
error CategoryAlreadyExists(string name);

// --- Department Errors ---
/// @notice Referenced department does not exist.
error DepartmentNotFound(uint256 departmentId);

/// @notice The department is deactivated and cannot accept new operations.
error DepartmentNotActive(uint256 departmentId);

/// @notice A department with this name already exists.
error DepartmentAlreadyExists(string name);

// --- Officer & Assignment Errors ---
/// @notice The officer is not registered in the specified department.
error OfficerNotInDepartment(address officer, uint256 departmentId);

/// @notice The grievance is not currently assigned to the caller.
error NotAssignedOfficer(uint256 grievanceId, address caller);

/// @notice The grievance has already been assigned to an officer.
error GrievanceAlreadyAssigned(uint256 grievanceId);

// --- Evidence Errors ---
/// @notice The IPFS CID string is empty.
error EmptyIPFSCid();

/// @notice The content hash is empty (bytes32(0)).
error EmptyContentHash();

/// @notice Referenced evidence does not exist.
error EvidenceNotFound(uint256 evidenceId);

// --- Resolution Errors ---
/// @notice Referenced resolution does not exist.
error ResolutionNotFound(uint256 resolutionId);

/// @notice A resolution is already pending citizen review for this grievance.
error ResolutionAlreadyPending(uint256 grievanceId);

// --- SLA & Escalation Errors ---
/// @notice The SLA deadline has not yet been breached; escalation is not permitted.
error SLANotBreached(uint256 grievanceId, uint64 deadline, uint64 currentTime);

/// @notice The grievance has already been escalated and awaits reassignment.
error AlreadyEscalated(uint256 grievanceId);

// --- General Validation ---
/// @notice A required string parameter is empty.
error EmptyString(string parameterName);

/// @notice A numeric value is out of the acceptable range.
error ValueOutOfRange(string parameterName, uint256 value, uint256 minValue, uint256 maxValue);

// --- Lifecycle State Errors ---
/// @notice The department is already active.
error DepartmentAlreadyActive(uint256 departmentId);

/// @notice The category is already active.
error CategoryAlreadyActive(uint256 categoryId);

/// @notice Department admin is not assigned for this department.
error DepartmentAdminNotAssigned(uint256 departmentId);

/// @notice The specified category does not belong to the responsible department.
error CategoryNotInDepartment(uint256 categoryId, uint256 departmentId);

contracts/IAuditTrail.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {AuditAction} from "./GrievanceTypes.sol";

/**
 * @title IAuditTrail
 * @notice Standard interface for the system-wide append-only audit trail ledger.
 *         Allows business contracts (RoleManager, DepartmentManager, GrievanceSystem,
 *         EscalationManager) to append immutable audit records without tight coupling
 *         or circular dependencies.
 */
interface IAuditTrail {
    /**
     * @notice Appends an immutable audit entry to the audit trail.
     * @dev Caller must be an authorized audit writer contract.
     *
     * @param action Categorized audit action from the AuditAction enum.
     * @param actor The wallet address that performed the action.
     * @param targetId Contextual target identifier (e.g., grievanceId, departmentId, or uint256(uint160(account))).
     * @param detailsHash keccak256 hash of metadata, parameters, or description for off-chain integrity.
     * @return auditId The unique, monotonically assigned audit record ID.
     */
    function recordAudit(
        AuditAction action,
        address actor,
        uint256 targetId,
        bytes32 detailsHash
    ) external returns (uint256 auditId);
}

contracts/DepartmentManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {RoleManager} from "./RoleManager.sol";
import {IAuditTrail} from "./IAuditTrail.sol";
import {
    Department,
    GrievanceCategory,
    AuditAction,
    // Errors
    Unauthorized,
    ZeroAddressNotAllowed,
    DepartmentNotFound,
    DepartmentNotActive,
    OfficerNotInDepartment,
    CategoryNotFound,
    CategoryNotActive,
    EmptyString,
    DepartmentAlreadyActive,
    CategoryAlreadyActive,
    CategoryAlreadyExists,
    DepartmentAdminNotAssigned
} from "./GrievanceTypes.sol";

/**
 * @title DepartmentManager
 * @notice Manages the organizational structure of the Blockchain-Based Public Grievance
 *         Tracking System: departments, officer-to-department membership, and dynamic
 *         grievance categories.
 *
 * This contract is the single source of truth for:
 *   1. Department registry — create, update, deactivate, assign admins.
 *   2. Officer-department membership — which officer belongs to which department(s).
 *   3. Grievance category registry — create, update, deactivate dynamic categories.
 *
 * Authorization model:
 *   - All role checks are delegated to the deployed RoleManager contract.
 *   - DepartmentManager NEVER grants or revokes global roles (that is RoleManager's job).
 *   - Super Admin can manage all departments, officers, and categories.
 *   - A Department Admin can only manage officers within the specific department to which
 *     they are assigned. They cannot touch other departments.
 *   - Citizens and Officers without admin privileges have no write access.
 *
 * Data integrity:
 *   - Department and category IDs start at 1 and increase monotonically. ID 0 is reserved.
 *   - Deactivation sets `isActive = false`. Records are NEVER deleted.
 *   - Historical events remain on the blockchain permanently for auditability.
 *   - Officer membership uses a mapping + array pattern for O(1) lookup and enumeration.
 *
 * Integration with future contracts:
 *   - GrievanceSystem.sol will call view functions like `isDepartmentActive()`,
 *     `isCategoryActive()`, and `isOfficerInDepartment()` for validation.
 *   - AuditTrail.sol will independently record audit entries based on events.
 */
contract DepartmentManager {

    // ========================================================================
    //  EXTERNAL DEPENDENCIES
    // ========================================================================

    /// @notice Reference to the deployed RoleManager contract for authorization checks.
    /// @dev Set once in the constructor and never changed.
    RoleManager public immutable roleManager;

    /// @notice Reference to the AuditTrail contract.
    address public auditTrail;

    // ========================================================================
    //  STATE — Departments
    // ========================================================================

    /// @dev Next department ID to assign. Starts at 1 so that ID 0 is reserved/invalid.
    uint256 private _nextDepartmentId = 1;

    /// @dev Department registry. Key = department ID.
    mapping(uint256 => Department) private _departments;

    // ========================================================================
    //  STATE — Officer Membership
    // ========================================================================

    /// @dev O(1) membership check: departmentId => officerAddress => isMember.
    mapping(uint256 => mapping(address => bool)) private _departmentOfficers;

    /// @dev Enumerable officer list per department for frontend getters.
    ///      departmentId => array of officer addresses.
    mapping(uint256 => address[]) private _departmentOfficersList;

    /// @dev Reverse index for swap-and-pop removal: departmentId => officer => arrayIndex.
    mapping(uint256 => mapping(address => uint256)) private _officerIndex;

    /// @dev Departments that an officer belongs to (for `getOfficerDepartments()`).
    ///      officerAddress => array of department IDs.
    mapping(address => uint256[]) private _officerDepartments;

    /// @dev Reverse index for swap-and-pop removal: officer => departmentId => arrayIndex.
    mapping(address => mapping(uint256 => uint256)) private _officerDeptIndex;

    // ========================================================================
    //  STATE — Categories
    // ========================================================================

    /// @dev Next category ID to assign. Starts at 1 so that ID 0 is reserved/invalid.
    uint256 private _nextCategoryId = 1;

    /// @dev Category registry. Key = category ID.
    mapping(uint256 => GrievanceCategory) private _categories;

    /// @dev Maps department ID to list of category IDs belonging to it.
    mapping(uint256 => uint256[]) private _departmentCategories;

    // ========================================================================
    //  CUSTOM ERRORS (contract-specific)
    // ========================================================================

    /// @notice The officer is already a member of the specified department.
    error OfficerAlreadyInDepartment(address officer, uint256 departmentId);

    /// @notice The target address does not hold the OFFICER_ROLE in RoleManager.
    error NotAnOfficer(address account);

    /// @notice The target address does not hold the DEPARTMENT_ADMIN_ROLE in RoleManager.
    error NotADepartmentAdmin(address account);

    // ========================================================================
    //  EVENTS
    // ========================================================================

    /// @notice Emitted when a new department is created.
    event DepartmentCreated(
        uint256 indexed departmentId,
        string name,
        address indexed admin,
        address indexed createdBy,
        uint64 timestamp
    );

    /// @notice Emitted when a department's name is updated.
    event DepartmentUpdated(
        uint256 indexed departmentId,
        string newName,
        address indexed updatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a department is deactivated.
    event DepartmentDeactivated(
        uint256 indexed departmentId,
        address indexed deactivatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a department's admin is changed.
    event DepartmentAdminChanged(
        uint256 indexed departmentId,
        address indexed previousAdmin,
        address indexed newAdmin,
        uint64 timestamp
    );

    /// @notice Emitted when an officer is added to a department.
    event OfficerAddedToDepartment(
        uint256 indexed departmentId,
        address indexed officer,
        address indexed addedBy,
        uint64 timestamp
    );

    /// @notice Emitted when an officer is removed from a department.
    event OfficerRemovedFromDepartment(
        uint256 indexed departmentId,
        address indexed officer,
        address indexed removedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a new category is created.
    event CategoryCreated(
        uint256 indexed categoryId,
        uint256 indexed departmentId,
        string name,
        address indexed createdBy,
        uint64 timestamp
    );

    /// @notice Emitted when a category is updated.
    event CategoryUpdated(
        uint256 indexed categoryId,
        string newName,
        address indexed updatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a category is deactivated.
    event CategoryDeactivated(
        uint256 indexed categoryId,
        address indexed deactivatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a department is reactivated.
    event DepartmentReactivated(
        uint256 indexed departmentId,
        address indexed reactivatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a department admin is removed/unassigned.
    event DepartmentAdminRemoved(
        uint256 indexed departmentId,
        address indexed previousAdmin,
        address indexed removedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a category is reactivated.
    event CategoryReactivated(
        uint256 indexed categoryId,
        address indexed reactivatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when an officer is transferred between departments.
    event OfficerDepartmentTransferred(
        address indexed officer,
        uint256 indexed fromDepartmentId,
        uint256 indexed toDepartmentId,
        address transferredBy,
        uint64 timestamp
    );

    /// @notice Emitted when the AuditTrail contract address is updated.
    event AuditTrailUpdated(address indexed previousAuditTrail, address indexed newAuditTrail);

    // ========================================================================
    //  MODIFIERS
    // ========================================================================

    /// @dev Restricts access to accounts holding SUPER_ADMIN_ROLE in RoleManager.
    modifier onlySuperAdmin() {
        if (!roleManager.isSuperAdmin(msg.sender)) {
            revert Unauthorized(msg.sender, "SUPER_ADMIN");
        }
        _;
    }

    /**
     * @dev Restricts access to Super Admin or the Department Admin assigned to the
     *      specified department. Prevents cross-department administration.
     *
     * @param departmentId The department being operated on.
     */
    modifier onlySuperAdminOrDeptAdminOf(uint256 departmentId) {
        if (!roleManager.isSuperAdmin(msg.sender)) {
            // Must hold the global DEPARTMENT_ADMIN_ROLE AND be the assigned admin
            if (!_isDepartmentAdminFor(departmentId, msg.sender)) {
                revert Unauthorized(msg.sender, "SUPER_ADMIN or assigned DEPARTMENT_ADMIN");
            }
        }
        _;
    }

    // ========================================================================
    //  CONSTRUCTOR
    // ========================================================================

    /**
     * @notice Deploys the DepartmentManager with a reference to the RoleManager.
     * @dev The RoleManager address is stored as `immutable` — it cannot be changed after
     *      deployment. This ensures a stable, tamper-proof authorization link.
     *
     * @param roleManagerAddress The deployed RoleManager contract address.
     */
    constructor(address roleManagerAddress) {
        if (roleManagerAddress == address(0)) {
            revert ZeroAddressNotAllowed();
        }
        roleManager = RoleManager(roleManagerAddress);
    }

    // ========================================================================
    //  AUDIT TRAIL CONFIGURATION
    // ========================================================================

    /**
     * @notice Sets or updates the AuditTrail contract address.
     * @dev Only callable by Super Admin.
     * @param _auditTrail The address of the deployed AuditTrail contract.
     */
    function setAuditTrail(address _auditTrail) external onlySuperAdmin {
        if (_auditTrail == address(0)) revert ZeroAddressNotAllowed();
        address oldAudit = auditTrail;
        auditTrail = _auditTrail;
        emit AuditTrailUpdated(oldAudit, _auditTrail);
    }

    // ========================================================================
    //  DEPARTMENT MANAGEMENT
    // ========================================================================

    /**
     * @notice Creates a new department.
     * @dev Only callable by Super Admin. The admin address must already hold
     *      DEPARTMENT_ADMIN_ROLE in RoleManager. This contract does NOT grant roles.
     *
     * @param name  The department name (cannot be empty).
     * @param admin The address of the Department Admin who will manage this department.
     * @return departmentId The unique ID of the newly created department.
     */
    function createDepartment(
        string calldata name,
        address admin
    ) external onlySuperAdmin returns (uint256 departmentId) {
        // Validate inputs
        if (bytes(name).length == 0) revert EmptyString("name");
        if (admin == address(0)) revert ZeroAddressNotAllowed();
        if (!roleManager.isDepartmentAdmin(admin)) revert NotADepartmentAdmin(admin);

        // Assign ID and create record
        departmentId = _nextDepartmentId++;
        uint64 now_ = uint64(block.timestamp);

        _departments[departmentId] = Department({
            id: departmentId,
            name: name,
            admin: admin,
            isActive: true,
            createdAt: now_,
            updatedAt: now_
        });

        emit DepartmentCreated(departmentId, name, admin, msg.sender, now_);

        _recordAudit(
            AuditAction.DEPARTMENT_CREATED,
            msg.sender,
            departmentId,
            keccak256(bytes(name))
        );
    }

    /**
     * @notice Updates the name of an existing department.
     * @dev Only callable by Super Admin. Department must exist and be active.
     *
     * @param departmentId The department to update.
     * @param newName      The new department name (cannot be empty).
     */
    function updateDepartment(
        uint256 departmentId,
        string calldata newName
    ) external onlySuperAdmin {
        _requireDepartmentExists(departmentId);
        _requireDepartmentActive(departmentId);
        if (bytes(newName).length == 0) revert EmptyString("name");

        Department storage dept = _departments[departmentId];
        dept.name = newName;
        dept.updatedAt = uint64(block.timestamp);

        emit DepartmentUpdated(departmentId, newName, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.DEPARTMENT_UPDATED,
            msg.sender,
            departmentId,
            keccak256(bytes(newName))
        );
    }

    /**
     * @notice Deactivates a department.
     * @dev Only callable by Super Admin. Sets `isActive = false`. The department record
     *      is NOT deleted — historical grievances may reference this department ID.
     *      Officers are NOT automatically removed; their membership records remain.
     *
     * @param departmentId The department to deactivate.
     */
    function deactivateDepartment(uint256 departmentId) external onlySuperAdmin {
        _requireDepartmentExists(departmentId);
        _requireDepartmentActive(departmentId);

        Department storage dept = _departments[departmentId];
        dept.isActive = false;
        dept.updatedAt = uint64(block.timestamp);

        emit DepartmentDeactivated(departmentId, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.DEPARTMENT_DEACTIVATED,
            msg.sender,
            departmentId,
            bytes32(0)
        );
    }

    /**
     * @notice Reactivates a previously deactivated department.
     * @dev Only callable by Super Admin. Sets `isActive = true`.
     * @param departmentId The department to reactivate.
     */
    function reactivateDepartment(uint256 departmentId) public onlySuperAdmin {
        _requireDepartmentExists(departmentId);
        if (_departments[departmentId].isActive) {
            revert DepartmentAlreadyActive(departmentId);
        }

        Department storage dept = _departments[departmentId];
        dept.isActive = true;
        dept.updatedAt = uint64(block.timestamp);

        emit DepartmentReactivated(departmentId, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.DEPARTMENT_ACTIVATED,
            msg.sender,
            departmentId,
            bytes32(0)
        );
    }

    /**
     * @notice Alias for reactivateDepartment to ensure API compatibility.
     * @param departmentId The department to activate.
     */
    function activateDepartment(uint256 departmentId) external onlySuperAdmin {
        reactivateDepartment(departmentId);
    }

    /**
     * @notice Removes/unassigns the admin from a department.
     * @dev Only callable by Super Admin.
     * @param departmentId The department whose admin is being removed.
     */
    function removeDepartmentAdmin(uint256 departmentId) external onlySuperAdmin {
        _requireDepartmentExists(departmentId);

        Department storage dept = _departments[departmentId];
        address previousAdmin = dept.admin;
        if (previousAdmin == address(0)) {
            revert DepartmentAdminNotAssigned(departmentId);
        }

        dept.admin = address(0);
        dept.updatedAt = uint64(block.timestamp);

        emit DepartmentAdminRemoved(departmentId, previousAdmin, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.DEPARTMENT_ADMIN_REMOVED,
            msg.sender,
            departmentId,
            bytes32(uint256(uint160(previousAdmin)))
        );
    }

    /**
     * @notice Changes the admin responsible for a department.
     * @dev Only callable by Super Admin. The new admin must hold DEPARTMENT_ADMIN_ROLE
     *      in RoleManager. This does NOT grant or revoke the global role — only changes
     *      which Department Admin is assigned to this specific department.
     *
     * @param departmentId The department whose admin is being changed.
     * @param newAdmin     The new Department Admin address.
     */
    function setDepartmentAdmin(
        uint256 departmentId,
        address newAdmin
    ) external onlySuperAdmin {
        _requireDepartmentExists(departmentId);
        _requireDepartmentActive(departmentId);
        if (newAdmin == address(0)) revert ZeroAddressNotAllowed();
        if (!roleManager.isDepartmentAdmin(newAdmin)) revert NotADepartmentAdmin(newAdmin);

        Department storage dept = _departments[departmentId];
        address previousAdmin = dept.admin;
        dept.admin = newAdmin;
        dept.updatedAt = uint64(block.timestamp);

        emit DepartmentAdminChanged(departmentId, previousAdmin, newAdmin, uint64(block.timestamp));

        _recordAudit(
            AuditAction.DEPARTMENT_ADMIN_ASSIGNED,
            msg.sender,
            departmentId,
            bytes32(uint256(uint160(newAdmin)))
        );
    }

    // ========================================================================
    //  OFFICER MEMBERSHIP
    // ========================================================================

    /**
     * @notice Adds an officer to a department.
     * @dev Callable by Super Admin or the Department Admin assigned to this department.
     *
     *      Prerequisites (all enforced):
     *      1. Department must exist and be active.
     *      2. Officer address must not be zero.
     *      3. Officer must hold OFFICER_ROLE in RoleManager.
     *      4. Officer must not already be a member of this department.
     *
     *      This function does NOT grant OFFICER_ROLE. If the address lacks the role
     *      in RoleManager, the call reverts with NotAnOfficer.
     *
     * @param departmentId The department to add the officer to.
     * @param officer      The officer's wallet address.
     */
    function addOfficerToDepartment(
        uint256 departmentId,
        address officer
    ) external onlySuperAdminOrDeptAdminOf(departmentId) {
        _requireDepartmentExists(departmentId);
        _requireDepartmentActive(departmentId);
        if (officer == address(0)) revert ZeroAddressNotAllowed();
        if (!roleManager.isOfficer(officer)) revert NotAnOfficer(officer);
        if (_departmentOfficers[departmentId][officer]) {
            revert OfficerAlreadyInDepartment(officer, departmentId);
        }

        // Mark membership
        _departmentOfficers[departmentId][officer] = true;

        // Add to department's officer list
        _officerIndex[departmentId][officer] = _departmentOfficersList[departmentId].length;
        _departmentOfficersList[departmentId].push(officer);

        // Add to officer's department list
        _officerDeptIndex[officer][departmentId] = _officerDepartments[officer].length;
        _officerDepartments[officer].push(departmentId);

        emit OfficerAddedToDepartment(departmentId, officer, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.OFFICER_ADDED,
            msg.sender,
            departmentId,
            bytes32(uint256(uint160(officer)))
        );
    }

    /**
     * @notice Removes an officer from a department.
     * @dev Callable by Super Admin or the Department Admin assigned to this department.
     *
     *      This does NOT revoke the officer's global OFFICER_ROLE — that remains a
     *      RoleManager responsibility. Only department membership is removed.
     *
     *      Uses swap-and-pop for O(1) array removal while maintaining index consistency.
     *
     * @param departmentId The department to remove the officer from.
     * @param officer      The officer's wallet address.
     */
    function removeOfficerFromDepartment(
        uint256 departmentId,
        address officer
    ) external onlySuperAdminOrDeptAdminOf(departmentId) {
        _requireDepartmentExists(departmentId);
        if (officer == address(0)) revert ZeroAddressNotAllowed();
        if (!_departmentOfficers[departmentId][officer]) {
            revert OfficerNotInDepartment(officer, departmentId);
        }

        // Clear membership flag
        _departmentOfficers[departmentId][officer] = false;

        // Swap-and-pop from department's officer list
        _removeFromAddressArray(
            _departmentOfficersList[departmentId],
            _officerIndex[departmentId],
            officer
        );

        // Swap-and-pop from officer's department list
        _removeFromUintArray(
            _officerDepartments[officer],
            _officerDeptIndex[officer],
            departmentId
        );

        emit OfficerRemovedFromDepartment(departmentId, officer, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.OFFICER_REMOVED,
            msg.sender,
            departmentId,
            bytes32(uint256(uint160(officer)))
        );
    }

    /**
     * @notice Transfers an officer from one department to another.
     * @dev Callable by Super Admin or Department Admin of the origin department.
     * @param officer The officer to transfer.
     * @param fromDepartmentId Current department ID.
     * @param toDepartmentId Target department ID (must exist and be active).
     */
    function transferOfficerDepartment(
        address officer,
        uint256 fromDepartmentId,
        uint256 toDepartmentId
    ) external onlySuperAdminOrDeptAdminOf(fromDepartmentId) {
        _requireDepartmentExists(fromDepartmentId);
        _requireDepartmentExists(toDepartmentId);
        _requireDepartmentActive(toDepartmentId);
        if (officer == address(0)) revert ZeroAddressNotAllowed();
        if (!_departmentOfficers[fromDepartmentId][officer]) {
            revert OfficerNotInDepartment(officer, fromDepartmentId);
        }
        if (_departmentOfficers[toDepartmentId][officer]) {
            revert OfficerAlreadyInDepartment(officer, toDepartmentId);
        }

        // Remove from origin
        _departmentOfficers[fromDepartmentId][officer] = false;
        _removeFromAddressArray(
            _departmentOfficersList[fromDepartmentId],
            _officerIndex[fromDepartmentId],
            officer
        );
        _removeFromUintArray(
            _officerDepartments[officer],
            _officerDeptIndex[officer],
            fromDepartmentId
        );

        // Add to destination
        _departmentOfficers[toDepartmentId][officer] = true;
        _officerIndex[toDepartmentId][officer] = _departmentOfficersList[toDepartmentId].length;
        _departmentOfficersList[toDepartmentId].push(officer);
        _officerDeptIndex[officer][toDepartmentId] = _officerDepartments[officer].length;
        _officerDepartments[officer].push(toDepartmentId);

        emit OfficerDepartmentTransferred(officer, fromDepartmentId, toDepartmentId, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.OFFICER_REMOVED,
            msg.sender,
            fromDepartmentId,
            bytes32(uint256(uint160(officer)))
        );
        _recordAudit(
            AuditAction.OFFICER_ADDED,
            msg.sender,
            toDepartmentId,
            bytes32(uint256(uint160(officer)))
        );
    }

    // ========================================================================
    // ========================================================================
    //  CATEGORY MANAGEMENT
    // ========================================================================

    /**
     * @notice Creates a new grievance category assigned to a specific department.
     * @dev Only callable by Super Admin or the assigned Department Admin for that department.
     *
     * @param departmentId The department this category belongs to.
     * @param name         The category name (cannot be empty).
     * @param description  A brief description of what this category covers.
     * @return categoryId  The unique ID of the newly created category.
     */
    function createCategory(
        uint256 departmentId,
        string calldata name,
        string calldata description
    ) external onlySuperAdminOrDeptAdminOf(departmentId) returns (uint256 categoryId) {
        _requireDepartmentExists(departmentId);
        _requireDepartmentActive(departmentId);
        if (bytes(name).length == 0) revert EmptyString("name");

        // Deterministic duplicate check: prevent active duplicate category name in the same department
        uint256[] storage deptCatIds = _departmentCategories[departmentId];
        bytes32 nameHash = keccak256(bytes(name));
        for (uint256 i = 0; i < deptCatIds.length; i++) {
            uint256 cId = deptCatIds[i];
            if (_categories[cId].isActive && keccak256(bytes(_categories[cId].name)) == nameHash) {
                revert CategoryAlreadyExists(name);
            }
        }

        categoryId = _nextCategoryId++;
        uint64 now_ = uint64(block.timestamp);

        _categories[categoryId] = GrievanceCategory({
            id: categoryId,
            departmentId: departmentId,
            name: name,
            description: description,
            isActive: true,
            createdAt: now_
        });

        _departmentCategories[departmentId].push(categoryId);

        emit CategoryCreated(categoryId, departmentId, name, msg.sender, now_);

        _recordAudit(
            AuditAction.CATEGORY_CREATED,
            msg.sender,
            categoryId,
            keccak256(bytes(name))
        );
    }

    /**
     * @notice Creates a new global grievance category (departmentId = 0).
     * @dev Only callable by Super Admin. Maintained for backward compatibility and global defaults.
     *
     * @param name        The category name (cannot be empty).
     * @param description A brief description of what this category covers.
     * @return categoryId The unique ID of the newly created category.
     */
    function createCategory(
        string calldata name,
        string calldata description
    ) external onlySuperAdmin returns (uint256 categoryId) {
        if (bytes(name).length == 0) revert EmptyString("name");

        categoryId = _nextCategoryId++;
        uint64 now_ = uint64(block.timestamp);

        _categories[categoryId] = GrievanceCategory({
            id: categoryId,
            departmentId: 0,
            name: name,
            description: description,
            isActive: true,
            createdAt: now_
        });

        emit CategoryCreated(categoryId, 0, name, msg.sender, now_);

        _recordAudit(
            AuditAction.CATEGORY_CREATED,
            msg.sender,
            categoryId,
            keccak256(bytes(name))
        );
    }

    /**
     * @notice Updates an existing category's name and description.
     * @dev Callable by Super Admin or the assigned Department Admin for this category's department.
     *
     * @param categoryId  The category to update.
     * @param name        The new category name (cannot be empty).
     * @param description The new category description.
     */
    function updateCategory(
        uint256 categoryId,
        string calldata name,
        string calldata description
    ) external {
        _requireCategoryExists(categoryId);
        _requireCategoryActive(categoryId);
        _requireSuperAdminOrDeptAdminOf(_categories[categoryId].departmentId);
        if (bytes(name).length == 0) revert EmptyString("name");

        GrievanceCategory storage cat = _categories[categoryId];
        cat.name = name;
        cat.description = description;

        emit CategoryUpdated(categoryId, name, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.CATEGORY_UPDATED,
            msg.sender,
            categoryId,
            keccak256(bytes(name))
        );
    }

    /**
     * @notice Deactivates a category.
     * @dev Callable by Super Admin or the assigned Department Admin for this category's department.
     *      Sets `isActive = false`. The category record is NOT deleted.
     *
     * @param categoryId The category to deactivate.
     */
    function deactivateCategory(uint256 categoryId) external {
        _requireCategoryExists(categoryId);
        _requireCategoryActive(categoryId);
        _requireSuperAdminOrDeptAdminOf(_categories[categoryId].departmentId);

        _categories[categoryId].isActive = false;

        emit CategoryDeactivated(categoryId, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.CATEGORY_DEACTIVATED,
            msg.sender,
            categoryId,
            bytes32(0)
        );
    }

    /**
     * @notice Reactivates a previously deactivated category.
     * @dev Callable by Super Admin or the assigned Department Admin for this category's department.
     * @param categoryId The category to reactivate.
     */
    function reactivateCategory(uint256 categoryId) public {
        _requireCategoryExists(categoryId);
        _requireSuperAdminOrDeptAdminOf(_categories[categoryId].departmentId);
        if (_categories[categoryId].isActive) {
            revert CategoryAlreadyActive(categoryId);
        }

        _categories[categoryId].isActive = true;

        emit CategoryReactivated(categoryId, msg.sender, uint64(block.timestamp));

        _recordAudit(
            AuditAction.CATEGORY_ACTIVATED,
            msg.sender,
            categoryId,
            bytes32(0)
        );
    }

    /**
     * @notice Alias for reactivateCategory.
     * @param categoryId The category to activate.
     */
    function activateCategory(uint256 categoryId) external {
        reactivateCategory(categoryId);
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Departments
    // ========================================================================

    /**
     * @notice Returns the full department record.
     * @param departmentId The department to query.
     * @return The Department struct.
     */
    function getDepartment(uint256 departmentId) external view returns (Department memory) {
        _requireDepartmentExists(departmentId);
        return _departments[departmentId];
    }

    /**
     * @notice Returns the admin address for a department.
     * @param departmentId The department to query.
     * @return The admin's wallet address.
     */
    function getDepartmentAdmin(uint256 departmentId) external view returns (address) {
        _requireDepartmentExists(departmentId);
        return _departments[departmentId].admin;
    }

    /**
     * @notice Returns all officers currently assigned to a department.
     * @dev Returns the full array. For departments with very large officer counts, consider
     *      off-chain indexing via events.
     *
     * @param departmentId The department to query.
     * @return An array of officer wallet addresses.
     */
    function getDepartmentOfficers(uint256 departmentId) external view returns (address[] memory) {
        _requireDepartmentExists(departmentId);
        return _departmentOfficersList[departmentId];
    }

    /**
     * @notice Returns the total number of departments ever created (including deactivated).
     * @return The total department count.
     */
    function getDepartmentCount() external view returns (uint256) {
        return _nextDepartmentId - 1;
    }

    /**
     * @notice Checks whether a department ID has been assigned.
     * @param departmentId The department ID to check.
     * @return True if the department exists (active or inactive).
     */
    function departmentExists(uint256 departmentId) external view returns (bool) {
        return _departmentExists(departmentId);
    }

    /**
     * @notice Checks whether a department is currently active.
     * @param departmentId The department ID to check.
     * @return True if the department exists and is active.
     */
    function isDepartmentActive(uint256 departmentId) external view returns (bool) {
        return _departmentExists(departmentId) && _departments[departmentId].isActive;
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Officer Membership
    // ========================================================================

    /**
     * @notice Checks whether an officer is a member of a specific department.
     * @param departmentId The department to check.
     * @param officer      The officer's wallet address.
     * @return True if the officer is currently a member of the department.
     */
    function isOfficerInDepartment(
        uint256 departmentId,
        address officer
    ) external view returns (bool) {
        return _departmentOfficers[departmentId][officer];
    }

    /**
     * @notice Returns all department IDs an officer currently belongs to.
     * @param officer The officer's wallet address.
     * @return An array of department IDs.
     */
    function getOfficerDepartments(address officer) external view returns (uint256[] memory) {
        return _officerDepartments[officer];
    }

    /**
     * @notice Returns the primary department ID of an officer (or 0 if none).
     * @param officer The officer's wallet address.
     * @return The primary department ID.
     */
    function getOfficerDepartment(address officer) external view returns (uint256) {
        if (_officerDepartments[officer].length > 0) {
            return _officerDepartments[officer][0];
        }
        return 0;
    }

    /**
     * @notice Checks whether an officer is active (has OFFICER_ROLE and is in at least one department).
     * @param officer The officer address to check.
     * @return True if active officer.
     */
    function isOfficerActive(address officer) external view returns (bool) {
        return roleManager.isOfficer(officer) && _officerDepartments[officer].length > 0;
    }

    /**
     * @notice Checks whether an account is the assigned Department Admin for a department.
     * @param departmentId The department ID.
     * @param account The address to check.
     * @return True if account is the assigned admin and holds DEPARTMENT_ADMIN_ROLE.
     */
    function isDepartmentAdminFor(uint256 departmentId, address account) external view returns (bool) {
        return _isDepartmentAdminFor(departmentId, account);
    }

    /**
     * @notice Returns all department IDs administered by a given address.
     * @param admin The department admin address.
     * @return An array of department IDs.
     */
    function getAdminDepartments(address admin) external view returns (uint256[] memory) {
        uint256 total = _nextDepartmentId - 1;
        uint256 count = 0;
        for (uint256 i = 1; i <= total; i++) {
            if (_departments[i].admin == admin) {
                count++;
            }
        }
        uint256[] memory ids = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 1; i <= total; i++) {
            if (_departments[i].admin == admin) {
                ids[idx] = i;
                idx++;
            }
        }
        return ids;
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Categories
    // ========================================================================

    /**
     * @notice Returns the full category record.
     * @param categoryId The category to query.
     * @return The GrievanceCategory struct.
     */
    function getCategory(uint256 categoryId) external view returns (GrievanceCategory memory) {
        _requireCategoryExists(categoryId);
        return _categories[categoryId];
    }

    /**
     * @notice Returns the total number of categories ever created (including deactivated).
     * @return The total category count.
     */
    function getCategoryCount() external view returns (uint256) {
        return _nextCategoryId - 1;
    }

    /**
     * @notice Checks whether a category ID has been assigned.
     * @param categoryId The category ID to check.
     * @return True if the category exists (active or inactive).
     */
    function categoryExists(uint256 categoryId) external view returns (bool) {
        return _categoryExists(categoryId);
    }

    /**
     * @notice Checks whether a category is currently active.
     * @param categoryId The category ID to check.
     * @return True if the category exists and is active.
     */
    function isCategoryActive(uint256 categoryId) external view returns (bool) {
        return _categoryExists(categoryId) && _categories[categoryId].isActive;
    }

    /**
     * @notice Returns all category IDs associated with a department.
     * @param departmentId The department ID to query.
     * @return Array of category IDs.
     */
    function getDepartmentCategories(uint256 departmentId) external view returns (uint256[] memory) {
        _requireDepartmentExists(departmentId);
        return _departmentCategories[departmentId];
    }

    /**
     * @notice Returns the department ID that a category belongs to.
     * @param categoryId The category ID to query.
     * @return The department ID (0 if global).
     */
    function getCategoryDepartment(uint256 categoryId) external view returns (uint256) {
        _requireCategoryExists(categoryId);
        return _categories[categoryId].departmentId;
    }

    // ========================================================================
    //  INTERNAL HELPERS — Validation
    // ========================================================================

    /**
     * @dev Checks if a department ID has been assigned (i.e., is within allocated range).
     * @param departmentId The department ID to check.
     * @return True if the ID is >= 1 and < _nextDepartmentId.
     */
    function _departmentExists(uint256 departmentId) internal view returns (bool) {
        return departmentId >= 1 && departmentId < _nextDepartmentId;
    }

    /// @dev Reverts with DepartmentNotFound if the department does not exist.
    function _requireDepartmentExists(uint256 departmentId) internal view {
        if (!_departmentExists(departmentId)) revert DepartmentNotFound(departmentId);
    }

    /// @dev Reverts with DepartmentNotActive if the department is not active.
    function _requireDepartmentActive(uint256 departmentId) internal view {
        if (!_departments[departmentId].isActive) revert DepartmentNotActive(departmentId);
    }

    /**
     * @dev Checks if a category ID has been assigned.
     * @param categoryId The category ID to check.
     * @return True if the ID is >= 1 and < _nextCategoryId.
     */
    function _categoryExists(uint256 categoryId) internal view returns (bool) {
        return categoryId >= 1 && categoryId < _nextCategoryId;
    }

    /// @dev Reverts with CategoryNotFound if the category does not exist.
    function _requireCategoryExists(uint256 categoryId) internal view {
        if (!_categoryExists(categoryId)) revert CategoryNotFound(categoryId);
    }

    /// @dev Reverts with CategoryNotActive if the category is not active.
    function _requireCategoryActive(uint256 categoryId) internal view {
        if (!_categories[categoryId].isActive) revert CategoryNotActive(categoryId);
    }

    // ========================================================================
    //  INTERNAL HELPERS — Authorization
    // ========================================================================

    /**
     * @dev Checks whether an account is the assigned Department Admin for a specific department.
     *      The account must hold DEPARTMENT_ADMIN_ROLE globally AND be the admin stored
     *      in the department record. This prevents cross-department administration.
     *
     * @param departmentId The department to check.
     * @param account      The address to verify.
     * @return True if the account is the assigned admin of the department.
     */
    function _isDepartmentAdminFor(
        uint256 departmentId,
        address account
    ) internal view returns (bool) {
        return
            roleManager.isDepartmentAdmin(account) &&
            _departments[departmentId].admin == account;
    }

    /**
     * @dev Reverts with Unauthorized unless msg.sender is Super Admin or the assigned Department Admin.
     * @param departmentId The department to check authorization against.
     */
    function _requireSuperAdminOrDeptAdminOf(uint256 departmentId) internal view {
        if (!roleManager.isSuperAdmin(msg.sender)) {
            if (departmentId == 0 || !_isDepartmentAdminFor(departmentId, msg.sender)) {
                revert Unauthorized(msg.sender, "SUPER_ADMIN or assigned DEPARTMENT_ADMIN");
            }
        }
    }

    // ========================================================================
    //  INTERNAL HELPERS — Array Management (Swap-and-Pop)
    // ========================================================================

    /**
     * @dev Removes an address from an array using swap-and-pop for O(1) removal.
     *      Updates the index mapping to keep it consistent.
     *
     * @param arr   The storage array to modify.
     * @param index The index mapping (address => position in array) to update.
     * @param value The address to remove.
     */
    function _removeFromAddressArray(
        address[] storage arr,
        mapping(address => uint256) storage index,
        address value
    ) internal {
        uint256 pos = index[value];
        uint256 lastPos = arr.length - 1;

        if (pos != lastPos) {
            address lastValue = arr[lastPos];
            arr[pos] = lastValue;
            index[lastValue] = pos;
        }

        arr.pop();
        delete index[value];
    }

    /**
     * @dev Removes a uint256 from an array using swap-and-pop for O(1) removal.
     *      Updates the index mapping to keep it consistent.
     *
     * @param arr   The storage array to modify.
     * @param index The index mapping (uint256 => position in array) to update.
     * @param value The uint256 to remove.
     */
    function _removeFromUintArray(
        uint256[] storage arr,
        mapping(uint256 => uint256) storage index,
        uint256 value
    ) internal {
        uint256 pos = index[value];
        uint256 lastPos = arr.length - 1;

        if (pos != lastPos) {
            uint256 lastValue = arr[lastPos];
            arr[pos] = lastValue;
            index[lastValue] = pos;
        }

        arr.pop();
        delete index[value];
    }

    // ========================================================================
    //  INTERNAL HELPERS — Audit Recording
    // ========================================================================

    /**
     * @dev Internal helper to record an audit entry if AuditTrail is configured.
     *      Atomic: reverts if recordAudit reverts.
     */
    function _recordAudit(
        AuditAction action,
        address actor,
        uint256 targetId,
        bytes32 detailsHash
    ) internal {
        if (auditTrail != address(0)) {
            IAuditTrail(auditTrail).recordAudit(action, actor, targetId, detailsHash);
        }
    }
}

contracts/GrievanceSystem.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {RoleManager} from "./RoleManager.sol";
import {DepartmentManager} from "./DepartmentManager.sol";
import {AuditTrail} from "./AuditTrail.sol";
import {
    Status,
    Priority,
    EvidenceType,
    ResolutionStatus,
    AuditAction,
    Grievance,
    Evidence,
    InvestigationNote,
    Assignment,
    Resolution,
    // Errors
    Unauthorized,
    ZeroAddressNotAllowed,
    GrievanceNotFound,
    InvalidStatusTransition,
    NotGrievanceOwner,
    InvalidTitle,
    CategoryNotFound,
    CategoryNotActive,
    DepartmentNotFound,
    DepartmentNotActive,
    OfficerNotInDepartment,
    NotAssignedOfficer,
    GrievanceAlreadyAssigned,
    EmptyIPFSCid,
    EmptyContentHash,
    EvidenceNotFound,
    ResolutionNotFound,
    ResolutionAlreadyPending,
    ValueOutOfRange,
    CategoryNotInDepartment
} from "./GrievanceTypes.sol";

/**
 * @title GrievanceSystem
 * @notice Central lifecycle and state management contract for the Blockchain-Based Public
 *         Grievance Tracking System.
 *
 * This contract is the authoritative source of truth for:
 *   1. Grievance intake and registration (Citizen submission -> Admin registration).
 *   2. Department and officer assignment with append-only assignment history.
 *   3. Controlled officer workflow: review -> investigation -> resolution proposal.
 *   4. Append-only investigation notes and dual-referenced (IPFS CID + Hash) evidence.
 *   5. Citizen feedback: accept, reject, and controlled reopening.
 *   6. Configurable SLA durations per priority tier.
 *
 * Authorization Architecture:
 *   - Strictly delegated to RoleManager (for global roles) and DepartmentManager
 *     (for department assignments and active status checks).
 *   - No arbitrary status mutation: status transitions are strictly governed by
 *     formal business functions matching the system lifecycle state machine.
 *
 * Immutability & Data Integrity:
 *   - Grievance, evidence, assignment, note, and resolution IDs are 1-indexed; ID 0 is reserved.
 *   - Historical records are NEVER deleted or overwritten.
 *   - Off-chain content uses the dual-reference pattern: IPFS CID for decentralized
 *     retrieval and bytes32 keccak256 hash for tamper-proof integrity verification.
 */
contract GrievanceSystem {

    // ========================================================================
    //  DEPENDENCIES
    // ========================================================================

    /// @notice Reference to the deployed RoleManager contract for role checks.
    RoleManager public immutable roleManager;

    /// @notice Reference to the deployed DepartmentManager for department & category checks.
    DepartmentManager public immutable departmentManager;

    /// @notice Authorized EscalationManager contract allowed to transition grievance escalation status.
    address public escalationManager;

    /// @notice Authorized AuditTrail contract.
    address public auditTrail;

    // ========================================================================
    //  STATE — Storage & Counters
    // ========================================================================

    /// @dev Next grievance ID to assign (starts at 1; ID 0 is reserved).
    uint256 private _nextGrievanceId = 1;

    /// @dev Primary grievance storage: grievanceId => Grievance struct.
    mapping(uint256 => Grievance) private _grievances;

    /// @dev Next assignment ID to assign (starts at 1).
    uint256 private _nextAssignmentId = 1;

    /// @dev Assignment history storage: assignmentId => Assignment struct.
    mapping(uint256 => Assignment) private _assignments;

    /// @dev Grievance to assignment IDs: grievanceId => array of assignment IDs.
    mapping(uint256 => uint256[]) private _grievanceAssignments;

    /// @dev Next investigation note ID to assign (starts at 1).
    uint256 private _nextNoteId = 1;

    /// @dev Investigation notes storage: noteId => InvestigationNote struct.
    mapping(uint256 => InvestigationNote) private _investigationNotes;

    /// @dev Grievance to note IDs: grievanceId => array of note IDs.
    mapping(uint256 => uint256[]) private _grievanceNotes;

    /// @dev Next evidence ID to assign (starts at 1).
    uint256 private _nextEvidenceId = 1;

    /// @dev Evidence storage: evidenceId => Evidence struct.
    mapping(uint256 => Evidence) private _evidences;

    /// @dev Grievance to evidence IDs: grievanceId => array of evidence IDs.
    mapping(uint256 => uint256[]) private _grievanceEvidences;

    /// @dev Next resolution ID to assign (starts at 1).
    uint256 private _nextResolutionId = 1;

    /// @dev Resolution storage: resolutionId => Resolution struct.
    mapping(uint256 => Resolution) private _resolutions;

    /// @dev Grievance to resolution IDs: grievanceId => array of resolution IDs.
    mapping(uint256 => uint256[]) private _grievanceResolutions;

    /// @dev SLA durations in seconds: Priority => duration in seconds.
    mapping(Priority => uint256) private _slaDurations;

    /// @dev Index grievances by citizen address: citizenAddress => array of grievance IDs.
    mapping(address => uint256[]) private _citizenGrievances;

    /// @dev Index grievances by assigned officer address: officerAddress => array of grievance IDs.
    mapping(address => uint256[]) private _officerGrievances;

    /// @dev Index grievances by department ID: departmentId => array of grievance IDs.
    mapping(uint256 => uint256[]) private _departmentGrievances;

    // ========================================================================
    //  CUSTOM ERRORS (Contract-Specific)
    // ========================================================================

    /// @notice Target officer is already assigned to this grievance.
    error CannotReassignToSameOfficer(uint256 grievanceId, address officer);

    /// @notice Attempted to revoke an evidence item that is already inactive/revoked.
    error EvidenceAlreadyRevoked(uint256 evidenceId);

    // ========================================================================
    //  EVENTS
    // ========================================================================

    /// @notice Emitted when a citizen creates a new grievance.
    event GrievanceCreated(
        uint256 indexed grievanceId,
        address indexed citizen,
        uint256 indexed departmentId,
        uint256 categoryId,
        Priority priority,
        uint64 slaDeadline,
        uint64 timestamp
    );

    /// @notice Emitted when an admin validates and registers intake of a grievance.
    event GrievanceRegistered(
        uint256 indexed grievanceId,
        address indexed actor,
        uint64 timestamp
    );

    /// @notice Emitted when an officer is assigned to a grievance.
    event GrievanceAssigned(
        uint256 indexed grievanceId,
        uint256 indexed assignmentId,
        uint256 indexed departmentId,
        address officer,
        address assignedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a grievance is reassigned to another officer.
    event GrievanceReassigned(
        uint256 indexed grievanceId,
        uint256 indexed assignmentId,
        uint256 indexed departmentId,
        address previousOfficer,
        address newOfficer,
        address reassignedBy,
        uint64 timestamp
    );

    /// @notice Emitted whenever a grievance transitions between statuses.
    event StatusChanged(
        uint256 indexed grievanceId,
        Status indexed previousStatus,
        Status indexed newStatus,
        address actor,
        uint64 timestamp
    );

    /// @notice Emitted when the assigned officer begins active investigation.
    event InvestigationStarted(
        uint256 indexed grievanceId,
        address indexed investigator,
        uint64 timestamp
    );

    /// @notice Emitted when an investigation note is appended.
    event InvestigationNoteAdded(
        uint256 indexed noteId,
        uint256 indexed grievanceId,
        address indexed investigator,
        string contentCid,
        bytes32 contentHash,
        uint64 timestamp
    );

    /// @notice Emitted when evidence metadata is attached to a grievance.
    event EvidenceAdded(
        uint256 indexed evidenceId,
        uint256 indexed grievanceId,
        address indexed submitter,
        EvidenceType evidenceType,
        string ipfsCid,
        bytes32 contentHash,
        uint64 timestamp
    );

    /// @notice Emitted when an evidence item is administratively revoked.
    event EvidenceRevoked(
        uint256 indexed evidenceId,
        uint256 indexed grievanceId,
        address indexed revokedBy,
        string reason,
        uint64 timestamp
    );

    /// @notice Emitted when the assigned officer submits a proposed resolution.
    event ResolutionSubmitted(
        uint256 indexed resolutionId,
        uint256 indexed grievanceId,
        address indexed proposedBy,
        string resolutionCid,
        bytes32 resolutionHash,
        uint64 timestamp
    );

    /// @notice Emitted when the citizen accepts the proposed resolution.
    event ResolutionAccepted(
        uint256 indexed resolutionId,
        uint256 indexed grievanceId,
        address indexed citizen,
        uint64 timestamp
    );

    /// @notice Emitted when the citizen rejects the proposed resolution.
    event ResolutionRejected(
        uint256 indexed resolutionId,
        uint256 indexed grievanceId,
        address indexed citizen,
        bytes32 rejectionReasonHash,
        uint64 timestamp
    );

    /// @notice Emitted when a citizen reopens a rejected grievance.
    event GrievanceReopened(
        uint256 indexed grievanceId,
        address indexed citizen,
        uint8 reopenCount,
        uint64 timestamp
    );

    /// @notice Emitted when a grievance is formally closed after acceptance.
    event GrievanceClosed(
        uint256 indexed grievanceId,
        address indexed closedBy,
        uint64 timestamp
    );

    /// @notice Emitted when a grievance is rejected by an administrator during intake or review.
    event GrievanceRejectedByAdmin(
        uint256 indexed grievanceId,
        address indexed rejectedBy,
        string reason,
        uint64 timestamp
    );

    /// @notice Emitted when the Super Admin updates the SLA duration for a priority tier.
    event SLAUpdated(
        Priority indexed priority,
        uint256 oldDuration,
        uint256 newDuration,
        address indexed updatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when the EscalationManager address is configured or updated.
    event EscalationManagerUpdated(
        address indexed previousManager,
        address indexed newManager,
        address indexed updatedBy,
        uint64 timestamp
    );

    /// @notice Emitted when the AuditTrail address is configured or updated.
    event AuditTrailUpdated(
        address indexed previousTrail,
        address indexed newTrail,
        address indexed updatedBy,
        uint64 timestamp
    );

    // ========================================================================
    //  MODIFIERS
    // ========================================================================

    /// @dev Restricts access to Super Admin in RoleManager.
    modifier onlySuperAdmin() {
        if (!roleManager.isSuperAdmin(msg.sender)) {
            revert Unauthorized(msg.sender, "SUPER_ADMIN");
        }
        _;
    }

    /// @dev Restricts access to Super Admin or the Department Admin assigned to the grievance's department.
    modifier onlySuperAdminOrDeptAdminFor(uint256 grievanceId) {
        _requireAdminForGrievance(grievanceId);
        _;
    }

    /// @dev Restricts access to the authorized EscalationManager contract.
    modifier onlyEscalationManager() {
        if (msg.sender != escalationManager) {
            revert Unauthorized(msg.sender, "ESCALATION_MANAGER");
        }
        _;
    }

    // ========================================================================
    //  CONSTRUCTOR
    // ========================================================================

    /**
     * @notice Initializes GrievanceSystem with references to RoleManager and DepartmentManager.
     * @param roleManagerAddress Deployed RoleManager address.
     * @param departmentManagerAddress Deployed DepartmentManager address.
     */
    constructor(address roleManagerAddress, address departmentManagerAddress) {
        if (roleManagerAddress == address(0) || departmentManagerAddress == address(0)) {
            revert ZeroAddressNotAllowed();
        }

        roleManager = RoleManager(roleManagerAddress);
        departmentManager = DepartmentManager(departmentManagerAddress);

        // Configure default SLA durations per priority tier
        _slaDurations[Priority.LOW] = 14 days;
        _slaDurations[Priority.MEDIUM] = 7 days;
        _slaDurations[Priority.HIGH] = 3 days;
        _slaDurations[Priority.CRITICAL] = 1 days;
    }

    // ========================================================================
    //  SLA CONFIGURATION
    // ========================================================================

    /**
     * @notice Updates the SLA duration for a priority tier.
     * @dev Only callable by Super Admin.
     * @param priority Target priority tier.
     * @param newDuration New duration in seconds (must be > 0).
     */
    function updateSlaDuration(Priority priority, uint256 newDuration) external onlySuperAdmin {
        if (newDuration == 0) {
            revert ValueOutOfRange("newDuration", 0, 1, type(uint256).max);
        }

        uint256 oldDuration = _slaDurations[priority];
        _slaDurations[priority] = newDuration;

        emit SLAUpdated(priority, oldDuration, newDuration, msg.sender, uint64(block.timestamp));
        _recordAudit(AuditAction.SLA_UPDATED, msg.sender, uint256(priority), bytes32(newDuration));
    }

    // ========================================================================
    //  GRIEVANCE CREATION
    // ========================================================================

    /**
     * @notice Submits a new grievance into the system.
     * @dev Only callable by a registered Citizen. Initial status is SUBMITTED.
     *
     * @param categoryId Category ID registered and active in DepartmentManager.
     * @param departmentId Department ID registered and active in DepartmentManager.
     * @param priority Priority tier for SLA deadline computation.
     * @param title Short summary title (1 to 200 bytes).
     * @param descriptionCid IPFS CID for full off-chain description.
     * @param descriptionHash keccak256 hash of description content for integrity verification.
     * @return grievanceId The assigned unique grievance identifier.
     */
    function createGrievance(
        uint256 categoryId,
        uint256 departmentId,
        Priority priority,
        string calldata title,
        string calldata descriptionCid,
        bytes32 descriptionHash
    ) external returns (uint256 grievanceId) {
        _validateGrievanceCreation(categoryId, departmentId, title, descriptionCid, descriptionHash);

        grievanceId = _nextGrievanceId++;
        uint64 now_ = uint64(block.timestamp);
        uint64 deadline = now_ + uint64(_slaDurations[priority]);

        Grievance storage g = _grievances[grievanceId];
        g.id = grievanceId;
        g.citizen = msg.sender;
        g.status = Status.SUBMITTED;
        g.priority = priority;
        g.reopenCount = 0;
        g.assignedOfficer = address(0);
        g.departmentId = departmentId;
        g.categoryId = categoryId;
        g.title = title;
        g.descriptionCid = descriptionCid;
        g.descriptionHash = descriptionHash;
        g.createdAt = now_;
        g.updatedAt = now_;
        g.slaDeadline = deadline;
        g.currentResolutionId = 0;

        _citizenGrievances[msg.sender].push(grievanceId);
        _departmentGrievances[departmentId].push(grievanceId);

        emit GrievanceCreated(
            grievanceId,
            msg.sender,
            departmentId,
            categoryId,
            priority,
            deadline,
            now_
        );

        emit StatusChanged(
            grievanceId,
            Status.SUBMITTED,
            Status.SUBMITTED,
            msg.sender,
            now_
        );

        _recordAudit(AuditAction.GRIEVANCE_CREATED, msg.sender, grievanceId, descriptionHash);
        return grievanceId;
    }

    // ========================================================================
    //  GRIEVANCE REGISTRATION & ASSIGNMENT
    // ========================================================================

    /**
     * @notice Registers intake for a submitted grievance (SUBMITTED -> REGISTERED).
     * @dev Callable by Super Admin or the Department Admin assigned to the grievance's department.
     * @param grievanceId Grievance ID to register.
     */
    function registerGrievance(uint256 grievanceId) external onlySuperAdminOrDeptAdminFor(grievanceId) {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.SUBMITTED) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.REGISTERED);
        }

        _transitionStatus(grievanceId, Status.REGISTERED);
        emit GrievanceRegistered(grievanceId, msg.sender, uint64(block.timestamp));
        _recordAudit(AuditAction.GRIEVANCE_REGISTERED, msg.sender, grievanceId, bytes32(0));
    }

    /**
     * @notice Rejects a grievance during intake, registration, or initial review.
     * @dev Callable by Super Admin or the assigned Department Admin for this grievance's department.
     * @param grievanceId The grievance ID to reject.
     * @param reason The administrative explanation for rejection.
     */
    function rejectGrievance(
        uint256 grievanceId,
        string calldata reason
    ) external onlySuperAdminOrDeptAdminFor(grievanceId) {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];
        Status current = g.status;
        if (
            current != Status.SUBMITTED &&
            current != Status.REGISTERED &&
            current != Status.UNDER_REVIEW
        ) {
            revert InvalidStatusTransition(grievanceId, current, Status.REJECTED);
        }

        _transitionStatus(grievanceId, Status.REJECTED);

        emit GrievanceRejectedByAdmin(grievanceId, msg.sender, reason, uint64(block.timestamp));
        _recordAudit(
            AuditAction.GRIEVANCE_REJECTED,
            msg.sender,
            grievanceId,
            keccak256(bytes(reason))
        );
    }

    /**
     * @notice Assigns an officer to a grievance (REGISTERED or REOPENED -> ASSIGNED).
     * @dev Callable by Super Admin or the Department Admin assigned to the grievance's department.
     *      Officer must belong to this specific grievance's department in DepartmentManager.
     *
     * @param grievanceId Grievance ID to assign.
     * @param officer Address of the officer to assign.
     */
    function assignOfficer(
        uint256 grievanceId,
        address officer
    ) external onlySuperAdminOrDeptAdminFor(grievanceId) {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        // Ensure grievance is in an assignable state
        if (g.status != Status.REGISTERED && g.status != Status.REOPENED) {
            if (g.status == Status.ASSIGNED) {
                revert GrievanceAlreadyAssigned(grievanceId);
            }
            revert InvalidStatusTransition(grievanceId, g.status, Status.ASSIGNED);
        }

        _validateOfficerForDepartment(g.departmentId, officer);

        // Record assignment
        uint256 assignmentId = _recordAssignment(grievanceId, g.departmentId, officer);
        g.assignedOfficer = officer;
        _officerGrievances[officer].push(grievanceId);

        _transitionStatus(grievanceId, Status.ASSIGNED);

        emit GrievanceAssigned(
            grievanceId,
            assignmentId,
            g.departmentId,
            officer,
            msg.sender,
            uint64(block.timestamp)
        );

        _recordAudit(AuditAction.GRIEVANCE_ASSIGNED, msg.sender, grievanceId, bytes32(uint256(uint160(officer))));
    }

    /**
     * @notice Reassigns a grievance to a different officer.
     * @dev Callable by Super Admin or assigned Department Admin during active handling.
     *
     * @param grievanceId Grievance ID to reassign.
     * @param newOfficer Address of the new officer.
     */
    function reassignOfficer(
        uint256 grievanceId,
        address newOfficer
    ) external onlySuperAdminOrDeptAdminFor(grievanceId) {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        // Must already be assigned or in investigation
        if (
            g.status != Status.ASSIGNED &&
            g.status != Status.UNDER_REVIEW &&
            g.status != Status.UNDER_INVESTIGATION &&
            g.status != Status.ESCALATED
        ) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.ASSIGNED);
        }

        if (newOfficer == g.assignedOfficer) {
            revert CannotReassignToSameOfficer(grievanceId, newOfficer);
        }

        _validateOfficerForDepartment(g.departmentId, newOfficer);

        address previousOfficer = g.assignedOfficer;
        uint256 assignmentId = _recordAssignment(grievanceId, g.departmentId, newOfficer);
        g.assignedOfficer = newOfficer;
        _officerGrievances[newOfficer].push(grievanceId);

        // If escalated or under investigation, keep or reset to ASSIGNED/UNDER_INVESTIGATION
        if (g.status == Status.ESCALATED) {
            _transitionStatus(grievanceId, Status.UNDER_INVESTIGATION);
        }

        emit GrievanceReassigned(
            grievanceId,
            assignmentId,
            g.departmentId,
            previousOfficer,
            newOfficer,
            msg.sender,
            uint64(block.timestamp)
        );

        _recordAudit(AuditAction.GRIEVANCE_REASSIGNED, msg.sender, grievanceId, bytes32(uint256(uint160(newOfficer))));
    }

    // ========================================================================
    //  OFFICER WORKFLOW
    // ========================================================================

    /**
     * @notice Starts review of an assigned grievance (ASSIGNED -> UNDER_REVIEW).
     * @dev Only callable by the currently assigned officer.
     * @param grievanceId Grievance ID.
     */
    function startReview(uint256 grievanceId) external {
        _requireAssignedOfficer(grievanceId);
        _transitionStatus(grievanceId, Status.UNDER_REVIEW);
    }

    /**
     * @notice Starts formal investigation (UNDER_REVIEW -> UNDER_INVESTIGATION).
     * @dev Only callable by the currently assigned officer.
     * @param grievanceId Grievance ID.
     */
    function startInvestigation(uint256 grievanceId) external {
        _requireAssignedOfficer(grievanceId);
        _transitionStatus(grievanceId, Status.UNDER_INVESTIGATION);
        emit InvestigationStarted(grievanceId, msg.sender, uint64(block.timestamp));
        _recordAudit(AuditAction.INVESTIGATION_STARTED, msg.sender, grievanceId, bytes32(0));
    }

    /**
     * @notice Appends an investigation note to a grievance under review/investigation.
     * @dev Only callable by the currently assigned officer. Append-only.
     *
     * @param grievanceId Grievance ID.
     * @param contentCid IPFS CID of note text.
     * @param contentHash keccak256 hash of note text.
     * @return noteId Unique identifier of the created investigation note.
     */
    function addInvestigationNote(
        uint256 grievanceId,
        string calldata contentCid,
        bytes32 contentHash
    ) external returns (uint256 noteId) {
        _requireAssignedOfficer(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.UNDER_REVIEW && g.status != Status.UNDER_INVESTIGATION) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.UNDER_INVESTIGATION);
        }
        if (bytes(contentCid).length == 0) revert EmptyIPFSCid();
        if (contentHash == bytes32(0)) revert EmptyContentHash();

        noteId = _nextNoteId++;
        uint64 now_ = uint64(block.timestamp);

        _investigationNotes[noteId] = InvestigationNote({
            id: noteId,
            grievanceId: grievanceId,
            investigator: msg.sender,
            contentCid: contentCid,
            contentHash: contentHash,
            timestamp: now_
        });

        _grievanceNotes[grievanceId].push(noteId);
        g.updatedAt = now_;

        emit InvestigationNoteAdded(
            noteId,
            grievanceId,
            msg.sender,
            contentCid,
            contentHash,
            now_
        );

        _recordAudit(AuditAction.INVESTIGATION_NOTE_ADDED, msg.sender, grievanceId, contentHash);
    }

    // ========================================================================
    //  EVIDENCE MANAGEMENT
    // ========================================================================

    /**
     * @notice Attaches evidence metadata to a grievance.
     * @dev Callable by the grievance's citizen, assigned officer, or authorized admins.
     *      Grievance must not be CLOSED.
     *
     * @param grievanceId Grievance ID.
     * @param evidenceType Classification enum.
     * @param ipfsCid IPFS CID for file retrieval.
     * @param contentHash keccak256 hash of the evidence file.
     * @return evidenceId Unique identifier of the attached evidence.
     */
    function addEvidence(
        uint256 grievanceId,
        EvidenceType evidenceType,
        string calldata ipfsCid,
        bytes32 contentHash
    ) external returns (uint256 evidenceId) {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status == Status.CLOSED) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.CLOSED);
        }
        if (bytes(ipfsCid).length == 0) revert EmptyIPFSCid();
        if (contentHash == bytes32(0)) revert EmptyContentHash();

        // Authorization: citizen, assigned officer, super admin, or dept admin for this dept
        bool isCitizenOwner = (msg.sender == g.citizen);
        bool isOfficerOwner = (msg.sender == g.assignedOfficer && roleManager.isOfficer(msg.sender));
        bool isSuperAdmin_ = roleManager.isSuperAdmin(msg.sender);
        bool isDeptAdmin_ = (
            roleManager.isDepartmentAdmin(msg.sender) &&
            departmentManager.getDepartmentAdmin(g.departmentId) == msg.sender
        );

        if (!isCitizenOwner && !isOfficerOwner && !isSuperAdmin_ && !isDeptAdmin_) {
            revert Unauthorized(msg.sender, "Citizen, Assigned Officer, or Department/Super Admin");
        }

        evidenceId = _nextEvidenceId++;
        uint64 now_ = uint64(block.timestamp);

        _evidences[evidenceId] = Evidence({
            id: evidenceId,
            grievanceId: grievanceId,
            submitter: msg.sender,
            evidenceType: evidenceType,
            isActive: true,
            ipfsCid: ipfsCid,
            contentHash: contentHash,
            submittedAt: now_
        });

        _grievanceEvidences[grievanceId].push(evidenceId);
        g.updatedAt = now_;

        emit EvidenceAdded(
            evidenceId,
            grievanceId,
            msg.sender,
            evidenceType,
            ipfsCid,
            contentHash,
            now_
        );

        _recordAudit(AuditAction.EVIDENCE_ADDED, msg.sender, grievanceId, contentHash);
    }

    /**
     * @notice Administratively revokes validity of an evidence record.
     * @dev Callable by Super Admin or assigned Department Admin. Does NOT delete data.
     *
     * @param evidenceId Evidence ID to revoke.
     * @param reason Human-readable audit explanation.
     */
    function revokeEvidence(
        uint256 evidenceId,
        string calldata reason
    ) external {
        if (evidenceId == 0 || evidenceId >= _nextEvidenceId) {
            revert EvidenceNotFound(evidenceId);
        }

        Evidence storage ev = _evidences[evidenceId];
        if (!ev.isActive) {
            revert EvidenceAlreadyRevoked(evidenceId);
        }

        _requireAdminForGrievance(ev.grievanceId);

        ev.isActive = false;
        emit EvidenceRevoked(evidenceId, ev.grievanceId, msg.sender, reason, uint64(block.timestamp));
        _recordAudit(AuditAction.EVIDENCE_REVOKED, msg.sender, ev.grievanceId, keccak256(bytes(reason)));
    }

    // ========================================================================
    //  RESOLUTION LIFECYCLE
    // ========================================================================

    /**
     * @notice Submits a resolution proposal (UNDER_INVESTIGATION -> RESOLUTION_PROPOSED -> CITIZEN_REVIEW).
     * @dev Only callable by the currently assigned officer.
     *
     * @param grievanceId Grievance ID.
     * @param resolutionCid IPFS CID describing the proposed resolution.
     * @param resolutionHash keccak256 hash of the resolution content.
     * @return resolutionId Unique identifier of the proposed resolution.
     */
    function submitResolution(
        uint256 grievanceId,
        string calldata resolutionCid,
        bytes32 resolutionHash
    ) public returns (uint256 resolutionId) {
        _requireAssignedOfficer(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.UNDER_INVESTIGATION) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.RESOLUTION_PROPOSED);
        }

        if (g.currentResolutionId != 0 && _resolutions[g.currentResolutionId].status == ResolutionStatus.PENDING) {
            revert ResolutionAlreadyPending(grievanceId);
        }

        if (bytes(resolutionCid).length == 0) revert EmptyIPFSCid();
        if (resolutionHash == bytes32(0)) revert EmptyContentHash();

        resolutionId = _nextResolutionId++;
        uint64 now_ = uint64(block.timestamp);

        _resolutions[resolutionId] = Resolution({
            id: resolutionId,
            grievanceId: grievanceId,
            proposedBy: msg.sender,
            status: ResolutionStatus.PENDING,
            resolutionCid: resolutionCid,
            resolutionHash: resolutionHash,
            rejectionReasonHash: bytes32(0),
            proposedAt: now_,
            reviewedAt: 0
        });

        _grievanceResolutions[grievanceId].push(resolutionId);
        g.currentResolutionId = resolutionId;

        // Transition through formal resolution proposed to citizen review
        _transitionStatus(grievanceId, Status.RESOLUTION_PROPOSED);
        _transitionStatus(grievanceId, Status.CITIZEN_REVIEW);

        emit ResolutionSubmitted(
            resolutionId,
            grievanceId,
            msg.sender,
            resolutionCid,
            resolutionHash,
            now_
        );

        _recordAudit(AuditAction.RESOLUTION_SUBMITTED, msg.sender, grievanceId, resolutionHash);
    }

    /**
     * @notice Alias for submitResolution to ensure API compatibility.
     * @param grievanceId Grievance ID.
     * @param resolutionCid IPFS CID for resolution description.
     * @param resolutionHash Content hash for integrity verification.
     * @return resolutionId Unique identifier of created resolution record.
     */
    function resolveGrievance(
        uint256 grievanceId,
        string calldata resolutionCid,
        bytes32 resolutionHash
    ) external returns (uint256 resolutionId) {
        return submitResolution(grievanceId, resolutionCid, resolutionHash);
    }

    /**
     * @notice Citizen accepts the proposed resolution (CITIZEN_REVIEW -> ACCEPTED).
     * @dev Only callable by the citizen who submitted this grievance.
     * @param grievanceId Grievance ID.
     */
    function acceptResolution(uint256 grievanceId) external {
        _requireGrievanceOwner(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.CITIZEN_REVIEW) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.ACCEPTED);
        }

        uint256 resId = g.currentResolutionId;
        if (resId == 0 || _resolutions[resId].status != ResolutionStatus.PENDING) {
            revert ResolutionNotFound(resId);
        }

        uint64 now_ = uint64(block.timestamp);
        _resolutions[resId].status = ResolutionStatus.ACCEPTED;
        _resolutions[resId].reviewedAt = now_;

        _transitionStatus(grievanceId, Status.ACCEPTED);

        emit ResolutionAccepted(resId, grievanceId, msg.sender, now_);
        _recordAudit(AuditAction.RESOLUTION_ACCEPTED, msg.sender, grievanceId, bytes32(0));
    }

    /**
     * @notice Citizen rejects the proposed resolution (CITIZEN_REVIEW -> REJECTED).
     * @dev Only callable by the citizen who submitted this grievance.
     *
     * @param grievanceId Grievance ID.
     * @param rejectionReasonHash keccak256 hash of the rejection rationale.
     */
    function rejectResolution(uint256 grievanceId, bytes32 rejectionReasonHash) external {
        _requireGrievanceOwner(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.CITIZEN_REVIEW) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.REJECTED);
        }
        if (rejectionReasonHash == bytes32(0)) {
            revert EmptyContentHash();
        }

        uint256 resId = g.currentResolutionId;
        if (resId == 0 || _resolutions[resId].status != ResolutionStatus.PENDING) {
            revert ResolutionNotFound(resId);
        }

        uint64 now_ = uint64(block.timestamp);
        _resolutions[resId].status = ResolutionStatus.REJECTED;
        _resolutions[resId].rejectionReasonHash = rejectionReasonHash;
        _resolutions[resId].reviewedAt = now_;

        _transitionStatus(grievanceId, Status.REJECTED);

        emit ResolutionRejected(resId, grievanceId, msg.sender, rejectionReasonHash, now_);
        _recordAudit(AuditAction.RESOLUTION_REJECTED, msg.sender, grievanceId, rejectionReasonHash);
    }

    /**
     * @notice Reopens a grievance after rejection (REJECTED -> REOPENED).
     * @dev Only callable by the citizen who filed the grievance.
     *      Increments reopenCount and enables reassignment.
     *
     * @param grievanceId Grievance ID.
     */
    function reopenGrievance(uint256 grievanceId) external {
        _requireGrievanceOwner(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.REJECTED) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.REOPENED);
        }

        if (g.reopenCount == type(uint8).max) {
            revert ValueOutOfRange("reopenCount", g.reopenCount, 0, type(uint8).max - 1);
        }

        g.reopenCount++;
        _transitionStatus(grievanceId, Status.REOPENED);

        emit GrievanceReopened(grievanceId, msg.sender, g.reopenCount, uint64(block.timestamp));
        _recordAudit(AuditAction.GRIEVANCE_REOPENED, msg.sender, grievanceId, bytes32(uint256(g.reopenCount)));
    }

    /**
     * @notice Formally closes an accepted grievance (ACCEPTED -> CLOSED).
     * @dev Callable by the citizen owner, Super Admin, or assigned Department Admin.
     * @param grievanceId Grievance ID.
     */
    function closeGrievance(uint256 grievanceId) external {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (g.status != Status.ACCEPTED) {
            revert InvalidStatusTransition(grievanceId, g.status, Status.CLOSED);
        }

        bool isCitizenOwner = (msg.sender == g.citizen);
        bool isSuperAdmin_ = roleManager.isSuperAdmin(msg.sender);
        bool isDeptAdmin_ = (
            roleManager.isDepartmentAdmin(msg.sender) &&
            departmentManager.getDepartmentAdmin(g.departmentId) == msg.sender
        );

        if (!isCitizenOwner && !isSuperAdmin_ && !isDeptAdmin_) {
            revert Unauthorized(msg.sender, "Citizen or Admin");
        }

        _transitionStatus(grievanceId, Status.CLOSED);
        emit GrievanceClosed(grievanceId, msg.sender, uint64(block.timestamp));
        _recordAudit(AuditAction.GRIEVANCE_CLOSED, msg.sender, grievanceId, bytes32(0));
    }

    // ========================================================================
    //  ESCALATION HOOKS (Authorized EscalationManager Only)
    // ========================================================================

    /**
     * @notice Configures the authorized EscalationManager contract.
     * @dev Only callable by Super Admin.
     * @param escalationManagerAddress Address of the deployed EscalationManager.
     */
    function setEscalationManager(address escalationManagerAddress) external onlySuperAdmin {
        if (escalationManagerAddress == address(0)) {
            revert ZeroAddressNotAllowed();
        }
        address previous = escalationManager;
        escalationManager = escalationManagerAddress;
        emit EscalationManagerUpdated(previous, escalationManagerAddress, msg.sender, uint64(block.timestamp));
    }

    /**
     * @notice Transitions a grievance to ESCALATED status upon verified SLA breach.
     * @dev Only callable by the authorized EscalationManager contract.
     * @param grievanceId The grievance ID to escalate.
     */
    function setEscalatedStatus(uint256 grievanceId) external onlyEscalationManager {
        _requireGrievanceExists(grievanceId);
        _transitionStatus(grievanceId, Status.ESCALATED);
    }

    /**
     * @notice Transitions an escalated grievance back to UNDER_INVESTIGATION status upon resolution.
     * @dev Only callable by the authorized EscalationManager contract.
     * @param grievanceId The grievance ID being returned to investigation.
     */
    function resolveEscalationStatus(uint256 grievanceId) external onlyEscalationManager {
        _requireGrievanceExists(grievanceId);
        _transitionStatus(grievanceId, Status.UNDER_INVESTIGATION);
    }

    // ========================================================================
    //  AUDIT HOOKS (Optional Authorized AuditTrail Integration)
    // ========================================================================

    /**
     * @notice Configures the authorized AuditTrail contract.
     * @dev Only callable by Super Admin.
     * @param auditTrailAddress Address of the deployed AuditTrail.
     */
    function setAuditTrail(address auditTrailAddress) external onlySuperAdmin {
        if (auditTrailAddress == address(0)) {
            revert ZeroAddressNotAllowed();
        }
        address previous = auditTrail;
        auditTrail = auditTrailAddress;
        emit AuditTrailUpdated(previous, auditTrailAddress, msg.sender, uint64(block.timestamp));
    }

    /**
     * @dev Internal helper that safely writes an audit record if AuditTrail is configured.
     */
    function _recordAudit(
        AuditAction action,
        address actor,
        uint256 targetId,
        bytes32 detailsHash
    ) internal {
        address at = auditTrail;
        if (at != address(0)) {
            AuditTrail(at).recordAudit(action, actor, targetId, detailsHash);
        }
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Grievances
    // ========================================================================

    /**
     * @notice Returns the full Grievance record.
     * @param grievanceId Grievance ID.
     * @return Grievance struct.
     */
    function getGrievance(uint256 grievanceId) external view returns (Grievance memory) {
        _requireGrievanceExists(grievanceId);
        return _grievances[grievanceId];
    }

    /**
     * @notice Checks whether a grievance exists.
     * @param grievanceId Grievance ID.
     * @return True if grievance exists.
     */
    function grievanceExists(uint256 grievanceId) external view returns (bool) {
        return _grievanceExists(grievanceId);
    }

    /**
     * @notice Returns total grievances created.
     * @return Total count.
     */
    function getGrievanceCount() external view returns (uint256) {
        return _nextGrievanceId - 1;
    }

    /**
     * @notice Returns the SLA duration for a priority tier.
     * @param priority Priority enum.
     * @return Duration in seconds.
     */
    function getSlaDuration(Priority priority) external view returns (uint256) {
        return _slaDurations[priority];
    }

    /**
     * @notice Returns the SLA deadline timestamp for a grievance.
     * @param grievanceId Grievance ID.
     * @return SLA deadline timestamp.
     */
    function getSlaDeadline(uint256 grievanceId) external view returns (uint64) {
        _requireGrievanceExists(grievanceId);
        return _grievances[grievanceId].slaDeadline;
    }

    /**
     * @notice Checks if an account is the citizen owner of a grievance.
     * @param grievanceId Grievance ID.
     * @param account Account address.
     * @return True if owner.
     */
    function isGrievanceOwner(uint256 grievanceId, address account) external view returns (bool) {
        if (!_grievanceExists(grievanceId)) return false;
        return _grievances[grievanceId].citizen == account;
    }

    /**
     * @notice Checks if an account is the assigned officer of a grievance.
     * @param grievanceId Grievance ID.
     * @param account Account address.
     * @return True if assigned officer.
     */
    function isAssignedOfficer(uint256 grievanceId, address account) external view returns (bool) {
        if (!_grievanceExists(grievanceId)) return false;
        return _grievances[grievanceId].assignedOfficer == account && account != address(0);
    }

    /**
     * @notice Checks if a grievance has exceeded its SLA deadline.
     * @param grievanceId Grievance ID.
     * @return True if past deadline and not yet closed/accepted.
     */
    function isGrievanceOverdue(uint256 grievanceId) external view returns (bool) {
        if (!_grievanceExists(grievanceId)) return false;
        Grievance storage g = _grievances[grievanceId];
        if (g.status == Status.CLOSED || g.status == Status.ACCEPTED) return false;
        return block.timestamp > g.slaDeadline;
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Assignments
    // ========================================================================

    /**
     * @notice Returns all assignment IDs associated with a grievance.
     * @param grievanceId Grievance ID.
     * @return Array of assignment IDs.
     */
    function getGrievanceAssignments(uint256 grievanceId) external view returns (uint256[] memory) {
        _requireGrievanceExists(grievanceId);
        return _grievanceAssignments[grievanceId];
    }

    /**
     * @notice Returns an Assignment record.
     * @param assignmentId Assignment ID.
     * @return Assignment struct.
     */
    function getAssignment(uint256 assignmentId) external view returns (Assignment memory) {
        if (assignmentId == 0 || assignmentId >= _nextAssignmentId) {
            revert ValueOutOfRange("assignmentId", assignmentId, 1, _nextAssignmentId - 1);
        }
        return _assignments[assignmentId];
    }

    /**
     * @notice Returns total assignments recorded.
     * @return Total count.
     */
    function getAssignmentCount() external view returns (uint256) {
        return _nextAssignmentId - 1;
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Investigation Notes
    // ========================================================================

    /**
     * @notice Returns all note IDs associated with a grievance.
     * @param grievanceId Grievance ID.
     * @return Array of note IDs.
     */
    function getGrievanceInvestigationNotes(uint256 grievanceId) external view returns (uint256[] memory) {
        _requireGrievanceExists(grievanceId);
        return _grievanceNotes[grievanceId];
    }

    /**
     * @notice Returns an InvestigationNote record.
     * @param noteId Note ID.
     * @return InvestigationNote struct.
     */
    function getInvestigationNote(uint256 noteId) external view returns (InvestigationNote memory) {
        if (noteId == 0 || noteId >= _nextNoteId) {
            revert ValueOutOfRange("noteId", noteId, 1, _nextNoteId - 1);
        }
        return _investigationNotes[noteId];
    }

    /**
     * @notice Returns total notes recorded.
     * @return Total count.
     */
    function getInvestigationNoteCount() external view returns (uint256) {
        return _nextNoteId - 1;
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Evidence
    // ========================================================================

    /**
     * @notice Returns all evidence IDs associated with a grievance.
     * @param grievanceId Grievance ID.
     * @return Array of evidence IDs.
     */
    function getGrievanceEvidence(uint256 grievanceId) external view returns (uint256[] memory) {
        _requireGrievanceExists(grievanceId);
        return _grievanceEvidences[grievanceId];
    }

    /**
     * @notice Returns an Evidence record.
     * @param evidenceId Evidence ID.
     * @return Evidence struct.
     */
    function getEvidence(uint256 evidenceId) external view returns (Evidence memory) {
        if (evidenceId == 0 || evidenceId >= _nextEvidenceId) {
            revert EvidenceNotFound(evidenceId);
        }
        return _evidences[evidenceId];
    }

    /**
     * @notice Returns total evidence records created.
     * @return Total count.
     */
    function getEvidenceCount() external view returns (uint256) {
        return _nextEvidenceId - 1;
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Resolutions
    // ========================================================================

    /**
     * @notice Returns all resolution IDs associated with a grievance.
     * @param grievanceId Grievance ID.
     * @return Array of resolution IDs.
     */
    function getGrievanceResolutions(uint256 grievanceId) external view returns (uint256[] memory) {
        _requireGrievanceExists(grievanceId);
        return _grievanceResolutions[grievanceId];
    }

    /**
     * @notice Returns a Resolution record.
     * @param resolutionId Resolution ID.
     * @return Resolution struct.
     */
    function getResolution(uint256 resolutionId) external view returns (Resolution memory) {
        if (resolutionId == 0 || resolutionId >= _nextResolutionId) {
            revert ResolutionNotFound(resolutionId);
        }
        return _resolutions[resolutionId];
    }

    /**
     * @notice Returns total resolutions created.
     * @return Total count.
     */
    function getResolutionCount() external view returns (uint256) {
        return _nextResolutionId - 1;
    }

    /**
     * @notice Returns all grievance IDs filed by a citizen.
     * @param citizen Citizen wallet address.
     * @return Array of grievance IDs.
     */
    function getCitizenGrievances(address citizen) external view returns (uint256[] memory) {
        return _citizenGrievances[citizen];
    }

    /**
     * @notice Returns all grievance IDs assigned to an officer.
     * @param officer Officer wallet address.
     * @return Array of grievance IDs.
     */
    function getOfficerGrievances(address officer) external view returns (uint256[] memory) {
        return _officerGrievances[officer];
    }

    /**
     * @notice Returns all grievance IDs belonging to a department.
     * @param departmentId Department ID.
     * @return Array of grievance IDs.
     */
    function getDepartmentGrievances(uint256 departmentId) external view returns (uint256[] memory) {
        return _departmentGrievances[departmentId];
    }

    // ========================================================================
    //  INTERNAL HELPERS — Validation & Transition
    // ========================================================================

    /// @dev Checks existence of a grievance ID within bounds.
    function _grievanceExists(uint256 grievanceId) internal view returns (bool) {
        return grievanceId >= 1 && grievanceId < _nextGrievanceId;
    }

    /// @dev Reverts if grievance does not exist.
    function _requireGrievanceExists(uint256 grievanceId) internal view {
        if (!_grievanceExists(grievanceId)) {
            revert GrievanceNotFound(grievanceId);
        }
    }

    /// @dev Reverts if caller is not the citizen who filed the grievance.
    function _requireGrievanceOwner(uint256 grievanceId) internal view {
        _requireGrievanceExists(grievanceId);
        if (_grievances[grievanceId].citizen != msg.sender) {
            revert NotGrievanceOwner(grievanceId, msg.sender);
        }
    }

    /// @dev Reverts if caller is not the currently assigned officer holding OFFICER_ROLE.
    function _requireAssignedOfficer(uint256 grievanceId) internal view {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (!roleManager.isOfficer(msg.sender) || g.assignedOfficer != msg.sender) {
            revert NotAssignedOfficer(grievanceId, msg.sender);
        }
    }

    /// @dev Reverts if caller is neither Super Admin nor assigned Department Admin for this grievance's dept.
    function _requireAdminForGrievance(uint256 grievanceId) internal view {
        _requireGrievanceExists(grievanceId);
        Grievance storage g = _grievances[grievanceId];

        if (!roleManager.isSuperAdmin(msg.sender)) {
            bool isAssignedDeptAdmin = (
                roleManager.isDepartmentAdmin(msg.sender) &&
                departmentManager.getDepartmentAdmin(g.departmentId) == msg.sender
            );
            if (!isAssignedDeptAdmin) {
                revert Unauthorized(msg.sender, "SUPER_ADMIN or assigned DEPARTMENT_ADMIN");
            }
        }
    }

    /// @dev Validates that an officer exists, is nonzero, holds OFFICER_ROLE, and belongs to the department.
    function _validateOfficerForDepartment(uint256 departmentId, address officer) internal view {
        if (officer == address(0)) revert ZeroAddressNotAllowed();
        if (!departmentManager.isDepartmentActive(departmentId)) revert DepartmentNotActive(departmentId);
        if (!roleManager.isOfficer(officer)) revert Unauthorized(officer, "OFFICER");
        if (!departmentManager.isOfficerInDepartment(departmentId, officer)) {
            revert OfficerNotInDepartment(officer, departmentId);
        }
    }

    /// @dev Creates an immutable Assignment record and links it to the grievance.
    function _recordAssignment(
        uint256 grievanceId,
        uint256 departmentId,
        address officer
    ) internal returns (uint256 assignmentId) {
        assignmentId = _nextAssignmentId++;
        uint64 now_ = uint64(block.timestamp);

        _assignments[assignmentId] = Assignment({
            grievanceId: grievanceId,
            departmentId: departmentId,
            assignedOfficer: officer,
            assignedBy: msg.sender,
            assignedAt: now_
        });

        _grievanceAssignments[grievanceId].push(assignmentId);
    }

    /**
     * @dev Validates whether a lifecycle status transition is permitted.
     */
    function _isValidTransition(Status from, Status to) internal pure returns (bool) {
        if (from == Status.SUBMITTED && to == Status.REGISTERED) return true;
        if (from == Status.REGISTERED && to == Status.ASSIGNED) return true;
        if (from == Status.REOPENED && to == Status.ASSIGNED) return true;
        if (from == Status.ASSIGNED && to == Status.UNDER_REVIEW) return true;
        if (from == Status.UNDER_REVIEW && to == Status.UNDER_INVESTIGATION) return true;
        if (from == Status.UNDER_INVESTIGATION && to == Status.RESOLUTION_PROPOSED) return true;
        if (from == Status.RESOLUTION_PROPOSED && to == Status.CITIZEN_REVIEW) return true;
        if (from == Status.CITIZEN_REVIEW && to == Status.ACCEPTED) return true;
        if (from == Status.CITIZEN_REVIEW && to == Status.REJECTED) return true;
        if ((from == Status.SUBMITTED || from == Status.REGISTERED || from == Status.UNDER_REVIEW) && to == Status.REJECTED) return true;
        if (from == Status.REJECTED && to == Status.REOPENED) return true;
        if (from == Status.ACCEPTED && to == Status.CLOSED) return true;
        // Escalation hooks reserved for future EscalationManager
        if (from == Status.UNDER_INVESTIGATION && to == Status.ESCALATED) return true;
        if (from == Status.ESCALATED && to == Status.UNDER_INVESTIGATION) return true;
        if (from == Status.ESCALATED && to == Status.ASSIGNED) return true;

        return false;
    }

    /**
     * @dev Executes an authorized status transition, updates timestamp, and emits event.
     */
    function _transitionStatus(uint256 grievanceId, Status newStatus) internal {
        Grievance storage g = _grievances[grievanceId];
        Status oldStatus = g.status;

        if (!_isValidTransition(oldStatus, newStatus)) {
            revert InvalidStatusTransition(grievanceId, oldStatus, newStatus);
        }

        g.status = newStatus;
        g.updatedAt = uint64(block.timestamp);

        emit StatusChanged(grievanceId, oldStatus, newStatus, msg.sender, g.updatedAt);
    }

    /**
     * @dev Internal helper to validate input parameters for grievance creation without blowing the stack.
     */
    function _validateGrievanceCreation(
        uint256 categoryId,
        uint256 departmentId,
        string calldata title,
        string calldata descriptionCid,
        bytes32 descriptionHash
    ) internal view {
        if (msg.sender == address(0)) revert ZeroAddressNotAllowed();

        if (!departmentManager.categoryExists(categoryId)) revert CategoryNotFound(categoryId);
        if (!departmentManager.isCategoryActive(categoryId)) revert CategoryNotActive(categoryId);
        if (!departmentManager.departmentExists(departmentId)) revert DepartmentNotFound(departmentId);
        if (!departmentManager.isDepartmentActive(departmentId)) revert DepartmentNotActive(departmentId);

        uint256 catDept = departmentManager.getCategoryDepartment(categoryId);
        if (catDept != 0 && catDept != departmentId) revert CategoryNotInDepartment(categoryId, departmentId);

        if (bytes(title).length == 0 || bytes(title).length > 200) revert InvalidTitle();
        if (bytes(descriptionCid).length == 0) revert EmptyIPFSCid();
        if (descriptionHash == bytes32(0)) revert EmptyContentHash();
    }
}

contracts/AuditTrail.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {RoleManager} from "./RoleManager.sol";
import {IAuditTrail} from "./IAuditTrail.sol";
import {
    AuditAction,
    AuditEntry,
    // Shared Custom Errors
    Unauthorized,
    ZeroAddressNotAllowed,
    ValueOutOfRange
} from "./GrievanceTypes.sol";

/**
 * @title AuditTrail
 * @notice Tamper-evident, append-only historical audit log for the Blockchain-Based Public
 *         Grievance Tracking System.
 *
 * Architecture:
 *   - Serves as the central immutable ledger for all auditable system mutations.
 *   - Only authorized writer contracts (RoleManager, DepartmentManager, GrievanceSystem,
 *     EscalationManager) may record audit entries.
 *   - Super Admin manages authorized writers via RoleManager access control.
 *   - Individual audit records are strictly append-only: once written, entries cannot be modified,
 *     overwritten, or deleted by any actor or administrator.
 *
 * Target ID Semantics:
 *   - Grievance actions (GRIEVANCE_*, STATUS_*, INVESTIGATION_*, EVIDENCE_*, RESOLUTION_*):
 *     targetId = unique grievanceId.
 *   - Department actions (DEPARTMENT_*, OFFICER_*): targetId = departmentId.
 *   - Category actions (CATEGORY_*): targetId = categoryId.
 *   - User / Role actions (USER_REGISTERED, ROLE_GRANTED, ROLE_REVOKED):
 *     targetId = uint256(uint160(accountAddress)).
 *   - System SLA actions (SLA_UPDATED): targetId = uint256(priorityTier).
 *
 * Integrity & Details Hash:
 *   - detailsHash represents a keccak256 commitment of off-chain metadata, parameters, or reasons.
 *   - If an action has no supplementary details, bytes32(0) is recorded.
 */
contract AuditTrail is IAuditTrail {

    // ========================================================================
    //  DEPENDENCIES
    // ========================================================================

    /// @notice Reference to RoleManager for authorization checks.
    RoleManager public immutable roleManager;

    // ========================================================================
    //  STATE — Counters & Storage
    // ========================================================================

    /// @dev Monotonically increasing audit entry counter (1-indexed; ID 0 is reserved).
    uint256 private _nextAuditId = 1;

    /// @dev Primary audit store: auditId => AuditEntry struct.
    mapping(uint256 => AuditEntry) private _auditEntries;

    /// @dev Authorized contract writers: contractAddress => isAuthorized.
    mapping(address => bool) private _authorizedWriters;

    /// @dev Index by target entity: targetId => array of audit IDs.
    mapping(uint256 => uint256[]) private _targetAudits;

    /// @dev Index by actor wallet: actorAddress => array of audit IDs.
    mapping(address => uint256[]) private _actorAudits;

    // ========================================================================
    //  CUSTOM ERRORS
    // ========================================================================

    /// @notice Caller is not an authorized audit writer contract.
    error WriterNotAuthorized(address caller);

    /// @notice Referenced audit entry does not exist.
    error AuditEntryNotFound(uint256 auditId);

    // ========================================================================
    //  EVENTS
    // ========================================================================

    /// @notice Emitted whenever a new audit entry is permanently recorded.
    event AuditRecorded(
        uint256 indexed auditId,
        AuditAction indexed action,
        address indexed actor,
        uint256 targetId,
        bytes32 detailsHash,
        uint64 timestamp
    );

    /// @notice Emitted when an authorized writer contract is added or revoked.
    event AuditWriterUpdated(
        address indexed writer,
        bool authorized,
        address indexed updatedBy,
        uint64 timestamp
    );

    // ========================================================================
    //  MODIFIERS
    // ========================================================================

    /// @dev Restricts execution to Super Admin in RoleManager.
    modifier onlySuperAdmin() {
        if (!roleManager.isSuperAdmin(msg.sender)) {
            revert Unauthorized(msg.sender, "SUPER_ADMIN");
        }
        _;
    }

    /// @dev Restricts execution to authorized writer contracts.
    modifier onlyAuthorizedWriter() {
        if (!_authorizedWriters[msg.sender]) {
            revert WriterNotAuthorized(msg.sender);
        }
        _;
    }

    // ========================================================================
    //  CONSTRUCTOR
    // ========================================================================

    /**
     * @notice Initializes AuditTrail with RoleManager reference for authorization.
     * @param roleManagerAddress Deployed RoleManager address.
     */
    constructor(address roleManagerAddress) {
        if (roleManagerAddress == address(0)) {
            revert ZeroAddressNotAllowed();
        }
        roleManager = RoleManager(roleManagerAddress);
    }

    // ========================================================================
    //  WRITER ADMINISTRATION
    // ========================================================================

    /**
     * @notice Authorizes or revokes a contract's permission to append audit entries.
     * @dev Only callable by Super Admin.
     * @param writer Contract address to authorize or revoke.
     * @param authorized True to authorize, false to revoke.
     */
    function setAuthorizedWriter(address writer, bool authorized) external onlySuperAdmin {
        if (writer == address(0)) {
            revert ZeroAddressNotAllowed();
        }

        _authorizedWriters[writer] = authorized;
        emit AuditWriterUpdated(writer, authorized, msg.sender, uint64(block.timestamp));
    }

    /**
     * @notice Checks whether an address is an authorized audit writer.
     * @param writer Address to check.
     * @return True if authorized.
     */
    function isAuthorizedWriter(address writer) external view returns (bool) {
        return _authorizedWriters[writer];
    }

    // ========================================================================
    //  AUDIT RECORDING
    // ========================================================================

    /**
     * @notice Appends an immutable audit entry to the audit trail.
     * @dev Only callable by authorized writer contracts.
     *      Records the actual originating actor provided by the caller contract.
     *
     * @param action The categorized audit action from the AuditAction enum.
     * @param actor The wallet address that performed the action (must be non-zero).
     * @param targetId Contextual target identifier (e.g., grievanceId, departmentId).
     * @param detailsHash keccak256 hash of off-chain metadata or description.
     * @return auditId The unique, monotonically assigned audit record ID.
     */
    function recordAudit(
        AuditAction action,
        address actor,
        uint256 targetId,
        bytes32 detailsHash
    ) external onlyAuthorizedWriter returns (uint256 auditId) {
        if (actor == address(0)) {
            revert ZeroAddressNotAllowed();
        }

        auditId = _nextAuditId++;
        uint64 now_ = uint64(block.timestamp);

        _auditEntries[auditId] = AuditEntry({
            id: auditId,
            action: action,
            actor: actor,
            targetId: targetId,
            detailsHash: detailsHash,
            timestamp: now_
        });

        _targetAudits[targetId].push(auditId);
        _actorAudits[actor].push(auditId);

        emit AuditRecorded(auditId, action, actor, targetId, detailsHash, now_);
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Audit Queries
    // ========================================================================

    /**
     * @notice Retrieves a specific audit entry by its unique ID.
     * @param auditId The audit entry identifier.
     * @return The AuditEntry struct.
     */
    function getAuditEntry(uint256 auditId) external view returns (AuditEntry memory) {
        if (auditId == 0 || auditId >= _nextAuditId) {
            revert AuditEntryNotFound(auditId);
        }
        return _auditEntries[auditId];
    }

    /**
     * @notice Checks whether an audit entry ID exists.
     * @param auditId The ID to check.
     * @return True if the audit entry exists.
     */
    function auditExists(uint256 auditId) external view returns (bool) {
        return auditId >= 1 && auditId < _nextAuditId;
    }

    /**
     * @notice Returns the total number of audit records created.
     * @return Total audit count.
     */
    function getAuditCount() external view returns (uint256) {
        return _nextAuditId - 1;
    }

    /**
     * @notice Returns all audit IDs associated with a specific target.
     * @param targetId The contextual target identifier (e.g., grievanceId).
     * @return Array of matching audit IDs.
     */
    function getAuditsByTarget(uint256 targetId) external view returns (uint256[] memory) {
        return _targetAudits[targetId];
    }

    /**
     * @notice Returns all audit IDs for actions performed by a specific actor.
     * @param actor The wallet address to query.
     * @return Array of matching audit IDs.
     */
    function getAuditsByActor(address actor) external view returns (uint256[] memory) {
        return _actorAudits[actor];
    }

    /**
     * @notice Returns a paginated range of audit entries for frontend inspection.
     * @dev Maximum batch size is 100 records to prevent block gas limits.
     *
     * @param startId Starting audit ID (inclusive, minimum 1).
     * @param endId Ending audit ID (inclusive, must be >= startId).
     * @return entries An array of AuditEntry structs within the specified range.
     */
    function getAuditEntries(
        uint256 startId,
        uint256 endId
    ) external view returns (AuditEntry[] memory entries) {
        if (startId == 0 || startId >= _nextAuditId) {
            revert ValueOutOfRange("startId", startId, 1, _nextAuditId > 1 ? _nextAuditId - 1 : 1);
        }

        uint256 lastId = _nextAuditId - 1;
        uint256 effectiveEnd = endId > lastId ? lastId : endId;

        if (effectiveEnd < startId) {
            revert ValueOutOfRange("endId", effectiveEnd, startId, lastId);
        }

        uint256 count = effectiveEnd - startId + 1;
        if (count > 100) {
            revert ValueOutOfRange("batchSize", count, 1, 100);
        }

        entries = new AuditEntry[](count);
        for (uint256 i = 0; i < count; i++) {
            entries[i] = _auditEntries[startId + i];
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {RoleManager} from "./RoleManager.sol";
import {IAuditTrail} from "./IAuditTrail.sol";
import {
    AuditAction,
    AuditEntry,
    // Shared Custom Errors
    Unauthorized,
    ZeroAddressNotAllowed,
    ValueOutOfRange
} from "./GrievanceTypes.sol";

/**
 * @title AuditTrail
 * @notice Tamper-evident, append-only historical audit log for the Blockchain-Based Public
 *         Grievance Tracking System.
 *
 * Architecture:
 *   - Serves as the central immutable ledger for all auditable system mutations.
 *   - Only authorized writer contracts (RoleManager, DepartmentManager, GrievanceSystem,
 *     EscalationManager) may record audit entries.
 *   - Super Admin manages authorized writers via RoleManager access control.
 *   - Individual audit records are strictly append-only: once written, entries cannot be modified,
 *     overwritten, or deleted by any actor or administrator.
 *
 * Target ID Semantics:
 *   - Grievance actions (GRIEVANCE_*, STATUS_*, INVESTIGATION_*, EVIDENCE_*, RESOLUTION_*):
 *     targetId = unique grievanceId.
 *   - Department actions (DEPARTMENT_*, OFFICER_*): targetId = departmentId.
 *   - Category actions (CATEGORY_*): targetId = categoryId.
 *   - User / Role actions (USER_REGISTERED, ROLE_GRANTED, ROLE_REVOKED):
 *     targetId = uint256(uint160(accountAddress)).
 *   - System SLA actions (SLA_UPDATED): targetId = uint256(priorityTier).
 *
 * Integrity & Details Hash:
 *   - detailsHash represents a keccak256 commitment of off-chain metadata, parameters, or reasons.
 *   - If an action has no supplementary details, bytes32(0) is recorded.
 */
contract AuditTrail is IAuditTrail {

    // ========================================================================
    //  DEPENDENCIES
    // ========================================================================

    /// @notice Reference to RoleManager for authorization checks.
    RoleManager public immutable roleManager;

    // ========================================================================
    //  STATE — Counters & Storage
    // ========================================================================

    /// @dev Monotonically increasing audit entry counter (1-indexed; ID 0 is reserved).
    uint256 private _nextAuditId = 1;

    /// @dev Primary audit store: auditId => AuditEntry struct.
    mapping(uint256 => AuditEntry) private _auditEntries;

    /// @dev Authorized contract writers: contractAddress => isAuthorized.
    mapping(address => bool) private _authorizedWriters;

    /// @dev Index by target entity: targetId => array of audit IDs.
    mapping(uint256 => uint256[]) private _targetAudits;

    /// @dev Index by actor wallet: actorAddress => array of audit IDs.
    mapping(address => uint256[]) private _actorAudits;

    // ========================================================================
    //  CUSTOM ERRORS
    // ========================================================================

    /// @notice Caller is not an authorized audit writer contract.
    error WriterNotAuthorized(address caller);

    /// @notice Referenced audit entry does not exist.
    error AuditEntryNotFound(uint256 auditId);

    // ========================================================================
    //  EVENTS
    // ========================================================================

    /// @notice Emitted whenever a new audit entry is permanently recorded.
    event AuditRecorded(
        uint256 indexed auditId,
        AuditAction indexed action,
        address indexed actor,
        uint256 targetId,
        bytes32 detailsHash,
        uint64 timestamp
    );

    /// @notice Emitted when an authorized writer contract is added or revoked.
    event AuditWriterUpdated(
        address indexed writer,
        bool authorized,
        address indexed updatedBy,
        uint64 timestamp
    );

    // ========================================================================
    //  MODIFIERS
    // ========================================================================

    /// @dev Restricts execution to Super Admin in RoleManager.
    modifier onlySuperAdmin() {
        if (!roleManager.isSuperAdmin(msg.sender)) {
            revert Unauthorized(msg.sender, "SUPER_ADMIN");
        }
        _;
    }

    /// @dev Restricts execution to authorized writer contracts.
    modifier onlyAuthorizedWriter() {
        if (!_authorizedWriters[msg.sender]) {
            revert WriterNotAuthorized(msg.sender);
        }
        _;
    }

    // ========================================================================
    //  CONSTRUCTOR
    // ========================================================================

    /**
     * @notice Initializes AuditTrail with RoleManager reference for authorization.
     * @param roleManagerAddress Deployed RoleManager address.
     */
    constructor(address roleManagerAddress) {
        if (roleManagerAddress == address(0)) {
            revert ZeroAddressNotAllowed();
        }
        roleManager = RoleManager(roleManagerAddress);
    }

    // ========================================================================
    //  WRITER ADMINISTRATION
    // ========================================================================

    /**
     * @notice Authorizes or revokes a contract's permission to append audit entries.
     * @dev Only callable by Super Admin.
     * @param writer Contract address to authorize or revoke.
     * @param authorized True to authorize, false to revoke.
     */
    function setAuthorizedWriter(address writer, bool authorized) external onlySuperAdmin {
        if (writer == address(0)) {
            revert ZeroAddressNotAllowed();
        }

        _authorizedWriters[writer] = authorized;
        emit AuditWriterUpdated(writer, authorized, msg.sender, uint64(block.timestamp));
    }

    /**
     * @notice Checks whether an address is an authorized audit writer.
     * @param writer Address to check.
     * @return True if authorized.
     */
    function isAuthorizedWriter(address writer) external view returns (bool) {
        return _authorizedWriters[writer];
    }

    // ========================================================================
    //  AUDIT RECORDING
    // ========================================================================

    /**
     * @notice Appends an immutable audit entry to the audit trail.
     * @dev Only callable by authorized writer contracts.
     *      Records the actual originating actor provided by the caller contract.
     *
     * @param action The categorized audit action from the AuditAction enum.
     * @param actor The wallet address that performed the action (must be non-zero).
     * @param targetId Contextual target identifier (e.g., grievanceId, departmentId).
     * @param detailsHash keccak256 hash of off-chain metadata or description.
     * @return auditId The unique, monotonically assigned audit record ID.
     */
    function recordAudit(
        AuditAction action,
        address actor,
        uint256 targetId,
        bytes32 detailsHash
    ) external onlyAuthorizedWriter returns (uint256 auditId) {
        if (actor == address(0)) {
            revert ZeroAddressNotAllowed();
        }

        auditId = _nextAuditId++;
        uint64 now_ = uint64(block.timestamp);

        _auditEntries[auditId] = AuditEntry({
            id: auditId,
            action: action,
            actor: actor,
            targetId: targetId,
            detailsHash: detailsHash,
            timestamp: now_
        });

        _targetAudits[targetId].push(auditId);
        _actorAudits[actor].push(auditId);

        emit AuditRecorded(auditId, action, actor, targetId, detailsHash, now_);
    }

    // ========================================================================
    //  VIEW FUNCTIONS — Audit Queries
    // ========================================================================

    /**
     * @notice Retrieves a specific audit entry by its unique ID.
     * @param auditId The audit entry identifier.
     * @return The AuditEntry struct.
     */
    function getAuditEntry(uint256 auditId) external view returns (AuditEntry memory) {
        if (auditId == 0 || auditId >= _nextAuditId) {
            revert AuditEntryNotFound(auditId);
        }
        return _auditEntries[auditId];
    }

    /**
     * @notice Checks whether an audit entry ID exists.
     * @param auditId The ID to check.
     * @return True if the audit entry exists.
     */
    function auditExists(uint256 auditId) external view returns (bool) {
        return auditId >= 1 && auditId < _nextAuditId;
    }

    /**
     * @notice Returns the total number of audit records created.
     * @return Total audit count.
     */
    function getAuditCount() external view returns (uint256) {
        return _nextAuditId - 1;
    }

    /**
     * @notice Returns all audit IDs associated with a specific target.
     * @param targetId The contextual target identifier (e.g., grievanceId).
     * @return Array of matching audit IDs.
     */
    function getAuditsByTarget(uint256 targetId) external view returns (uint256[] memory) {
        return _targetAudits[targetId];
    }

    /**
     * @notice Returns all audit IDs for actions performed by a specific actor.
     * @param actor The wallet address to query.
     * @return Array of matching audit IDs.
     */
    function getAuditsByActor(address actor) external view returns (uint256[] memory) {
        return _actorAudits[actor];
    }

    /**
     * @notice Returns a paginated range of audit entries for frontend inspection.
     * @dev Maximum batch size is 100 records to prevent block gas limits.
     *
     * @param startId Starting audit ID (inclusive, minimum 1).
     * @param endId Ending audit ID (inclusive, must be >= startId).
     * @return entries An array of AuditEntry structs within the specified range.
     */
    function getAuditEntries(
        uint256 startId,
        uint256 endId
    ) external view returns (AuditEntry[] memory entries) {
        if (startId == 0 || startId >= _nextAuditId) {
            revert ValueOutOfRange("startId", startId, 1, _nextAuditId > 1 ? _nextAuditId - 1 : 1);
        }

        uint256 lastId = _nextAuditId - 1;
        uint256 effectiveEnd = endId > lastId ? lastId : endId;

        if (effectiveEnd < startId) {
            revert ValueOutOfRange("endId", effectiveEnd, startId, lastId);
        }

        uint256 count = effectiveEnd - startId + 1;
        if (count > 100) {
            revert ValueOutOfRange("batchSize", count, 1, 100);
        }

        entries = new AuditEntry[](count);
        for (uint256 i = 0; i < count; i++) {
            entries[i] = _auditEntries[startId + i];
        }
    }
}

